-- v29.64 — Schweiz-Geo-DB: Kantone, Regionen, Gemeinden (Dörfer)
-- Quellen: Wikidata SPARQL (BFS/swisstopo-Daten) für Gemeinden/Kantone;
--          web-recherchierte, quellenbelegte Regionen-Infos (Höhenbänder, Landschaft, Pilz-Habitate).
-- Angewandt auf remote via Supabase-MCP als v29_64_ch_geo_db_schema_cantons + _ch_munis_01..07 + _ch_regions_01..05.
-- Diese Datei ist der idempotente Repo-Mirror (Source-of-Truth-Spiegel).

create table if not exists public.ch_cantons (
  code text primary key,
  name text not null,
  capital text,
  area_km2 numeric,
  joined_confederation integer,
  population integer,
  languages text,
  created_at timestamptz not null default now()
);

create table if not exists public.ch_regions (
  slug text primary key,
  name text not null,
  canton_codes text[] not null default '{}'::text[],
  region_type text,
  description text,
  altitude_min_m integer,
  altitude_max_m integer,
  landscape text,
  good_mushrooms text[] default '{}'::text[],
  foraging_notes text,
  highlights text,
  source text,
  created_at timestamptz not null default now()
);

create table if not exists public.ch_municipalities (
  bfs_number integer primary key,
  name text not null,
  canton_code text not null references public.ch_cantons(code),
  elevation_m integer,
  population integer,
  lat double precision,
  lon double precision,
  region_slug text references public.ch_regions(slug),
  created_at timestamptz not null default now()
);

create index if not exists idx_ch_muni_canton on public.ch_municipalities(canton_code);
create index if not exists idx_ch_muni_region on public.ch_municipalities(region_slug);
create index if not exists idx_ch_muni_lower_name on public.ch_municipalities(lower(name));
create index if not exists idx_ch_regions_cantons on public.ch_regions using gin(canton_codes);

alter table public.ch_cantons enable row level security;
alter table public.ch_regions enable row level security;
alter table public.ch_municipalities enable row level security;

drop policy if exists ch_cantons_read on public.ch_cantons;
create policy ch_cantons_read on public.ch_cantons for select to anon, authenticated using (true);
drop policy if exists ch_regions_read on public.ch_regions;
create policy ch_regions_read on public.ch_regions for select to anon, authenticated using (true);
drop policy if exists ch_municipalities_read on public.ch_municipalities;
create policy ch_municipalities_read on public.ch_municipalities for select to anon, authenticated using (true);

