insert into public.ch_regions (slug, name, canton_codes, region_type, description, altitude_min_m, altitude_max_m, landscape, good_mushrooms, foraging_notes, highlights, source) values
('sarganserland', 'Sarganserland', ARRAY['SG']::text[], 'Alpental', 'Das Sarganserland ist der südlichste Wahlkreis des Kantons St. Gallen und erstreckt sich über rund 30 km durch das Seeztal und den oberen Rheintalkessel zwischen Sargans, Walensee und Bad Ragaz. Es umfasst die Gemeinden Sargans, Mels, Vilters-Wangs, Bad Ragaz, Pfäfers, Flums, Walenstadt und Quarten. Die Landschaft reicht vom Talboden über bewaldete Mittellagen und Alpweiden bis ins Hochgebirge.', 419, 3239, 'Ausgeprägter Höhengradient vom Seez-/Rheintalboden (~420 m) bis in alpine Zonen. An den Hängen kalkgeprägte Berge (Alvier, Gonzen, Pizol-Vorland), daher überwiegend Kalk-Buchen-Tannenwälder in Mittellagen, höher Fichten-Tannen-Bergwald; Föhn schafft warme Mikroklimata um den Walensee. Talböden mit Auenwald-Resten (Esche, Erle) entlang Seez und Tamina.', ARRAY['Steinpilz','Totentrompete','Trompetenpfifferling','Semmelstoppelpilz','Edelreizker','Parasol','Morchel']::text[], 'Pilzsaison vorwiegend Juli bis Oktober. In den kalkreichen Buchen-Tannen-Mittellagen (600-1200 m) der Hänge von Alvier und Flumserberg gedeihen Steinpilz und Totentrompete; auf oberflächlich versauerten Stellen Trompetenpfifferling. Im Frühjahr Morcheln in den Auen-/Eschenwäldern der Talböden. Jeden Fund vor dem Verzehr zwingend bei der VAPKO-Pilzkontrolle prüfen lassen.', 'Höchste Erhebungen im Pizol-/Alviergebiet, der Walensee als prägender See, die Taminaschlucht bei Bad Ragaz sowie das Weisstannental und Calfeisental als naturnahe Seitentäler.', 'de.wikipedia.org/wiki/Wahlkreis_Sarganserland; en.wikipedia.org/wiki/Sarganserland; sg.ch (Waldregionen); waldwissen.net SwissFungi; awl.ch Pilzdatenbank'),
('st_galler_rheintal', 'St. Galler Rheintal', ARRAY['SG']::text[], 'Seitental', 'Das St. Galler Rheintal ist der linksrheinische Teil des Alpenrheintals zwischen Bad Ragaz und dem Bodensee. Der bis 5 km breite Talboden liegt zwischen ~480 m bei Sargans und ~400 m am Bodensee. Hauptorte sind Altstätten, Heerbrugg, Au, Widnau, Berneck und Rheineck. Im Westen steigen die Hänge zum Alpstein-Vorland und Hohen Kasten an.', 400, 1795, 'Breiter, landwirtschaftlich (Wein, Obst, Mais) genutzter Talboden, an den Westhängen Misch- und Buchenwälder über kalkreicher Unterlage des Alpstein-Vorlands (Hoher Kasten, Kamor). Tallagen mit Auen- und Eschenwald-Resten am Alten Rhein und Binnenkanal; höhere Hanglagen Buchen-Tannen-Wald.', ARRAY['Steinpilz','Totentrompete','Parasol','Semmelstoppelpilz','Morchel']::text[], 'An den bewaldeten Westhängen (Eichberg, Altstätten, Hoher Kasten-Fuss) in kalkigen Buchenwäldern ab Spätsommer Steinpilz und Totentrompete; auf Waldwiesen und an Waldrändern Parasol. Im Frühjahr Morcheln in den Auenwald-Resten der Talsohle. Funde grundsätzlich bei der VAPKO-Pilzkontrolle abklären lassen, bevor etwas gegessen wird.', 'Der Bodensee im Norden, der Hohe Kasten (1795 m) als markanter Alpstein-Eckpfeiler im Westen, der Alte Rhein als Grenzfluss zu Österreich und der warme, föhngeprägte Talkessel.', 'de.wikipedia.org/wiki/St._Galler_Rheintal; st.gallen-bodensee.ch; sg.ch Geografie/Wald; waldwissen.net SwissFungi'),
('toggenburg', 'Toggenburg', ARRAY['SG']::text[], 'Voralpental', 'Das Toggenburg ist eine Talschaft am oberen Lauf der Thur im Kanton St. Gallen, eingebettet zwischen Alpstein im Norden und den Churfirsten im Süden. Es wird vom Thurtal und vom Neckertal gebildet. Hauptorte sind Wattwil, Lichtensteig, Ebnat-Kappel, Nesslau und Wildhaus. Die hügelig-bergige Landschaft reicht von rund 550 m bis zum Säntis auf 2502 m.', 419, 2502, 'Mosaik aus kalkigem und saurem Untergrund: südlich die Kalkwände der Churfirsten und des Alpsteins (Kalk-Buchen-Tannenwald), im westlichen Teil Molasse und Flysch der Nagelfluhkette mit eher sauren Nadel-/Fichtenwäldern. Viele Hochmoore und Streuwiesen in den Mittellagen; ausgedehnte Fichten-Tannen-Bergwälder, 70% Privatwald.', ARRAY['Eierschwamm','Steinpilz','Maronenröhrling','Trompetenpfifferling','Totentrompete','Semmelstoppelpilz']::text[], 'In den sauren Fichten-/Nadelwäldern der Molasse- und Flyschlagen (Neckertal, Nagelfluhkette, 700-1400 m) wachsen Eierschwamm und Maronenröhrling von Juli bis Oktober; in den kalkigen Buchen-Tannen-Wäldern unter den Churfirsten Steinpilz und Totentrompete. Trompetenpfifferling auf moosig-sauren Böden. Sämtliche Funde vor dem Verzehr der VAPKO-Pilzkontrolle vorlegen.', 'Höchster Berg ist der Säntis (2502 m); prägend die Churfirsten-Kette über dem Walensee. Naturnahe Hochmoore und das Karstphänomen Wildenmannlisloch am Selun.', 'de.wikipedia.org/wiki/Toggenburg; sg.ch Waldregion 5 Toggenburg; toggenburg.swiss; waldwissen.net SwissFungi; awl.ch'),
('werdenberg', 'Werdenberg', ARRAY['SG']::text[], 'Seitental', 'Die Region Werdenberg liegt im Osten des Kantons St. Gallen, linksrheinisch im Alpenrheintal an der Ostflanke von Alvierkette, Margelchopf, Churfirsten und Alpstein. Sie umfasst die Gemeinden Sennwald, Gams, Grabs, Buchs, Sevelen und Wartau. Das Gebiet reicht vom Rheintalboden bis weit ins Alpsteingebirge; Grabs ist der grösste Waldbesitzer des Kantons.', 440, 2574, 'Steiler Übergang vom Rheintalboden zu kalkreichen Voralpen (Alpstein, Churfirsten, Alvier). An den Hängen ausgedehnte Buchen-Tannen- und Fichten-Tannen-Bergwälder über Kalk; Talböden mit Auen-/Eschenwald-Resten am Rhein. Hoher Waldanteil mit Schutzwald-Funktion in den Steillagen.', ARRAY['Steinpilz','Totentrompete','Trompetenpfifferling','Semmelstoppelpilz','Edelreizker','Parasol','Morchel']::text[], 'In den kalkigen Buchen-Tannen-Wäldern der Hanglagen oberhalb Grabs, Buchs und Sennwald (600-1300 m) ab Spätsommer Steinpilz, Totentrompete und Semmelstoppelpilz; Trompetenpfifferling auf oberflächlich versauerten Stellen. Frühjahrs-Morcheln in den Rhein-Auenwäldern. Jeden Fund vor dem Essen bei der VAPKO-Pilzkontrolle prüfen lassen.', 'Der Voralpsee auf 1123 m und das mittelalterliche Städtchen Werdenberg mit dem Werdenbergersee; markante Gipfel wie Alvier, Margelchopf und Gonzen sowie der Alpstein im Westen.', 'de.wikipedia.org/wiki/Region_Werdenberg; werdenberg.ch; grabs.ch; sg.ch Wald; waldwissen.net SwissFungi'),
('fuerstenland', 'Fürstenland', ARRAY['SG']::text[], 'Hügelland', 'Das Fürstenland (Alte Landschaft) ist das historische Gebiet der Fürstabtei St. Gallen und umfasst heute die Region zwischen der Stadt St. Gallen, Wil und Rorschach. Es ist ein sanftes Molasse-Hügelland mit Hauptorten Gossau, Flawil, Wil, Uzwil, Degersheim, Wittenbach und Waldkirch. Offene Kulturlandschaft mit Feldern, Bachtälern und Wäldern.', 530, 1061, 'Welliges Molasse-Hügelland (Mittelland) mit Moränenrücken, zwischen rund 530 m und gut 1000 m. Untergrund saure bis basenarme Molasse; Wälder als Buchen-Mischwälder und Fichten-Tannen-Forste, durchsetzt mit Tobel und Bachschluchten (z.B. Wissbachschlucht). Reichliche Grundwasservorkommen über undurchlässiger Molasse.', ARRAY['Eierschwamm','Steinpilz','Maronenröhrling','Parasol','Semmelstoppelpilz']::text[], 'In den Fichten- und Mischwäldern der Molasse-Hügel (Roserwald Gossau, Wälder um Flawil, Degersheim, Waldkirch, 600-1000 m) Eierschwamm und Maronenröhrling von Juli bis Oktober, in basenreicheren Buchenpartien auch Steinpilz; Parasol an Waldrändern und Wiesen. Funde stets der VAPKO-Pilzkontrolle vorlegen, bevor sie gegessen werden.', 'Höchster Punkt im Degersheimer Exklave Obergampen (1061 m); waldreiche Hügelzüge wie der Roserwald bei Gossau, ausgedehnte Moränenlandschaft und Tobel-Bachtäler.', 'en.wikipedia.org/wiki/Fürstenland; hls-dhs-dss.ch Alte Landschaft; de.wikipedia.org/wiki/Gossau_SG; de.wikipedia.org/wiki/Degersheim_SG; sg.ch Waldregion 1; hikr.org'),
('appenzellerland', 'Appenzellerland / Alpstein', ARRAY['AR','AI']::text[], 'Voralpen', 'Das Appenzellerland umfasst die beiden Halbkantone Appenzell Ausserrhoden und Appenzell Innerrhoden, vollständig vom Kanton St. Gallen umschlossen. Es ist eine hügelige, von Weideland und Streusiedlungen geprägte Voralpenlandschaft mit Hauptorten Appenzell, Herisau, Urnäsch, Gais und Teufen, die sich südwärts zum Alpstein-Kalkmassiv mit dem Säntis erhebt.', 500, 2502, 'Zweigeteilt: im Norden welliges Molasse-Hügelland mit Weideland und eher spärlichem Wald, im Süden das Kalk-Faltengebirge Alpstein. Wälder als Buchen-Tannen- und Fichten-Tannen-Bestände; an den Kalkhängen des Alpsteins basenreiche Buchenwälder, in den Streusiedlungs-Hügeln Mischwald über Molasse. Mittlere Höhe rund 800 m.', ARRAY['Steinpilz','Eierschwamm','Totentrompete','Trompetenpfifferling','Semmelstoppelpilz','Parasol']::text[], 'In den kalkreichen Buchen-Tannen-Wäldern an den Alpstein-Hängen und in den Tobeln von Sitter und Urnäsch (600-1300 m) ab Spätsommer Steinpilz und Totentrompete; in den saureren Molasse-Hügelwäldern Eierschwamm und Trompetenpfifferling. Wegen des hohen Weideland-Anteils Parasol auf Waldwiesen. Jeden Fund vor dem Verzehr bei der VAPKO-Pilzkontrolle abklären lassen.', 'Höchster Berg ist der Säntis (2502 m) im Alpstein-Kalkmassiv mit Karsthöhlen, Dolinen und dem Seealpsee; die Flüsse Sitter, Urnäsch, Rotbach und Goldach durchziehen die bewaldeten Tobel.', 'de.wikipedia.org/wiki/Appenzellerland; en.wikipedia.org/wiki/Alpstein; appenzell.ch; ostschweiz.ch; waldwissen.net SwissFungi; awl.ch'),
('linthgebiet_linthebene', 'Linthgebiet & Linthebene', ARRAY['SG','GL','SZ']::text[], 'Seeregion', 'Die Linthebene ist die flache, entwässerte Talebene zwischen Walensee und Zürichsee, benannt nach der Linth. Sie liegt grösstenteils auf rund 405-420 m und gehört zu den Kantonen St. Gallen (Gaster/See: Weesen, Schänis, Kaltbrunn, Benken, Uznach), Glarus (Bilten, Niederurnen, Näfels, Mollis) und Schwyz. Umgeben von bewaldeten Hügeln wie Buchberg und Benkner Büchel.', 405, 900, 'Flache, ursprünglich versumpfte und durch das Linthwerk entwässerte Ebene mit Auen-, Riet- und Feuchtgebietsresten (Kaltbrunner Riet, Gäsi). Die umrahmenden Hügel (Buchberg, Benkner Büchel) und unteren Hänge tragen Buchen-Misch- und Eichen-Hagebuchen-Wälder; Talböden mit Eschen-Erlen-Auenwald über grundwassernahem, teils kalkhaltigem Boden.', ARRAY['Morchel','Steinpilz','Parasol','Totentrompete','Semmelstoppelpilz']::text[], 'Im Frühjahr (April/Mai) Morcheln in den Auen- und Eschenwäldern sowie an Wegrändern der grundwassernahen Ebene; ab Spätsommer in den Buchen-Mischwäldern der umliegenden Hügel (Buchberg, Benkner Büchel, Schänis) Steinpilz, Totentrompete und Parasol. Funde immer der VAPKO-Pilzkontrolle vorlegen, bevor etwas gegessen wird.', 'Eingebettet zwischen Walensee und Zürichsee, mit dem Linthkanal als prägendem Wasserbauwerk, den Naturschutzgebieten Kaltbrunner Riet und Gäsi (Walensee-Ufer) sowie den bewaldeten Inselbergen Buchberg und Benkner Büchel.', 'de.wikipedia.org/wiki/Linthebene; en.wikipedia.org/wiki/Linth; lebensraum-linthebene.ch; sg.ch Linth; waldwissen.net SwissFungi'),
('glarnerland', 'Glarnerland', ARRAY['GL']::text[], 'Alpental', 'Das Glarnerland (Kanton Glarus) umfasst das Einzugsgebiet der Linth bis zum Walensee samt Linthebene und Kerenzerberg. Es gliedert sich in das Haupttal (Linthtal), das Sernftal und das Klöntal. Hauptorte sind Glarus, Näfels, Mollis, Schwanden und Linthal. Vom flachen Talboden auf 414 m steigt das Gelände bis zum Tödi auf 3614 m.', 414, 3614, 'In der montanen Stufe (Talboden bis ~1300 m) Klimaxwald aus Buche, Weisstanne und Bergahorn; höher Fichten-Tannen-Bergwald. Untergrund geologisch komplex (Glarner Hauptüberschiebung, Verrucano), mit kalkigen wie sauren Partien. Föhn schafft milde Talklimata (südländische Flora am Walensee). Steile, schutzwaldreiche Hänge.', ARRAY['Steinpilz','Eierschwamm','Maronenröhrling','Trompetenpfifferling','Totentrompete','Semmelstoppelpilz']::text[], 'In den montanen Buchen-Weisstannen-Wäldern und Fichten-Tannen-Bergwäldern von Linthtal, Sernftal und Klöntal (500-1400 m) von Juli bis Oktober Steinpilz, Eierschwamm und Maronenröhrling; in basenreicheren Buchenpartien Totentrompete und Semmelstoppelpilz. Jeden Fund vor dem Verzehr zwingend bei der VAPKO-Pilzkontrolle prüfen lassen.', 'Höchster Berg ist der Tödi (3614 m); die berühmte Glarner Hauptüberschiebung (UNESCO-Welterbe Tektonikarena Sardona) bei der Lochsite, dazu Walensee und Klöntalersee als prägende Seen.', 'de.wikipedia.org/wiki/Kanton_Glarus; de.wikipedia.org/wiki/Glarner_Alpen; gl.ch Portrait; geopark-guide.ch; waldwissen.net SwissFungi'),
('oberengadin', 'Oberengadin', ARRAY['GR']::text[], 'Alpental / Hochtal', 'Inneralpines Hochtal im Süden Graubündens entlang des oberen Inn, von Maloja bis Zuoz. Charakteristisch sind die Engadiner Seenplatte (Silser-, Silvaplaner-, Champfèr- und St. Moritzersee) und die lichten Lärchen-Arven-Weidewälder. Hauptorte: St. Moritz, Samedan, Pontresina, Silvaplana, Sils, Zuoz.', 1600, 2200, 'Subalpine bis hochmontane Nadelwälder auf eher saurem/silikatischem Boden. Dominant sind Lärche (Larix) und Arve/Zirbe (Pinus cembra), die bis ca. 2200 m steigen, dazu einzelne Fichten. Lichte, krautreiche Lärchen-Weidewälder mit moosig-beerigem Unterwuchs — typischer Mykorrhiza-Lebensraum von Reizkern und Eierschwämmen.', ARRAY['Eierschwamm (Pfifferling)','Edelreizker','Fichten-Steinpilz','Maronenröhrling','Trompetenpfifferling','Semmelstoppelpilz']::text[], 'Hochmontane bis subalpine Lage: Saison beginnt spät (Hochsommer bis Frühherbst, ca. Juli–Oktober), Hauptfundzonen sind die lichten Lärchen-Arvenwälder und moosigen Nadelwaldränder zwischen 1700–2200 m. Edelreizker typisch unter Lärchen/Arven, Eierschwämme im Moos feuchter Mulden. Beachte Graubünden: Schonzeit 1.–10. jedes Monats, max. 2 kg/Person/Tag. Jeden Fund vor dem Verzehr zwingend von der VAPKO-Pilzkontrolle prüfen lassen.', 'Engadiner Seenplatte (Silser-, Silvaplaner-, St. Moritzersee); umrahmt von Berninagruppe-Gipfeln; weltbekannte goldene Lärchenfärbung Ende Sep–Anf Nov.', 'de.wikipedia.org/wiki/Oberengadin; nationalpark.ch (Lärche/Arve); gr.ch Artenförderung Pilze; waldwissen.net SwissFungi'),
('unterengadin', 'Unterengadin', ARRAY['GR']::text[], 'Alpental', 'Unterer Teil des Schweizer Inntals zwischen Zernez und der österreichischen Grenze bei Martina, enger und wilder als das Oberengadin. Der Inn durchfliesst mehrere Schluchten. Hauptorte: Scuol (~1200 m), Zernez, Susch, Lavin, Guarda, Ardez, Ftan, Sent, Ramosch.', 1019, 2300, 'Steileres Tal (1610–1019 m) mit gemischten Bergwäldern; Böden teils kalkhaltig, teils sauer je nach Hang. Dominant Lärche, Arve und Föhre; im God da Tamangur (S-charl) steht der höchstgelegene geschlossene Arvenwald Europas. Mischung aus subalpinem Nadelwald und montanen Föhren-/Lärchenhängen.', ARRAY['Fichten-Steinpilz','Eierschwamm (Pfifferling)','Edelreizker','Maronenröhrling','Trompetenpfifferling','Semmelstoppelpilz']::text[], 'Montane bis subalpine Nadel- und Mischwälder; Saison Hochsommer–Herbst (ca. Juli–Oktober). Föhren-/Lärchenwälder der sonnigen Terrassen (Ardez, Ftan, Sent) für Reizker und Steinpilze, feuchtere Nadelwaldböden für Eierschwämme und Trompetenpfifferlinge. Nationalpark-Zonen sind Sammelverbot. Graubünden: Schonzeit 1.–10., max. 2 kg/Tag. Jeden Fund vor dem Verzehr von der VAPKO-Pilzkontrolle prüfen lassen.', 'Piz Linard (3410 m), höchster Gipfel; God da Tamangur — höchster Arvenwald Europas; Schweizerischer Nationalpark angrenzend; Mineralquellen von Scuol.', 'de.wikipedia.org/wiki/Unterengadin; de.wikipedia.org/wiki/Tamangur; nationalpark.ch (Arve/Lärche); gr.ch häufigste Baumarten'),
('surselva', 'Surselva', ARRAY['GR']::text[], 'Tal / Landschaft', 'Talregion des Vorderrheins vom Oberalppass im Westen bis zum Zusammenfluss mit dem Hinterrhein bei Reichenau. Der rätoromanische Name bedeutet ''oberhalb des Waldes''. Hauptorte Ilanz und Disentis/Mustér; Seitentäler Val Medel, Val Sumvitg, Val Lumnezia und Valser Tal.', 600, 2000, 'Überwiegend Wald und Weide; höhere Lagen mit Fichten- und Lärchenwäldern, im Uaul Scatlè einer der höchstgelegenen Fichten-Urwälder Europas. Geologie kalkalpin mit grossen Anteilen des Flimser Bergsturzschutts (Ruinaulta/Rheinschlucht). Montane Fichtenwälder, subalpine Lärchen-Arven- und Bergföhrenbestände.', ARRAY['Fichten-Steinpilz','Eierschwamm (Pfifferling)','Maronenröhrling','Trompetenpfifferling','Edelreizker','Semmelstoppelpilz','Krause Glucke']::text[], 'Breites Höhenband: montane Fichten-/Mischwälder (Ilanz, Gruob, Ruinaulta) ab Spätsommer, subalpine Lärchen-/Bergföhrenwälder (Disentis, Val Medel) bis in den Herbst (ca. Juli–Oktober). Krause Glucke an Föhren/Kiefern, Steinpilze und Maronen in den sauren Fichtenwäldern, Eierschwämme im Moos der Bachtobel. Graubünden: Schonzeit 1.–10., max. 2 kg/Tag. Jeden Fund vor dem Verzehr von der VAPKO-Pilzkontrolle prüfen lassen.', 'Ruinaulta (Rheinschlucht) mit Auenwald Uaul Grond; Uaul Scatlè Fichten-Urwald; Gipfel Piz Terri (3149 m), Piz Greina (3124 m).', 'de.wikipedia.org/wiki/Surselva; en.wikipedia.org/wiki/Surselva_Region; surselva.info; waldwissen.net SwissFungi'),
('praettigau', 'Prättigau', ARRAY['GR']::text[], 'Tal / Sohlental', 'Rund 40 km langes Tal entlang der Landquart von Landquart bis Klosters, mit zahlreichen Seitentälern. Im Norden begrenzt vom Rätikon, im Süden grenzt es an Schanfigg und Davos. Hauptorte: Klosters, Schiers, Küblis, Grüsch, Seewis.', 576, 2300, 'Geologisch dominiert Bündnerschiefer → eher saure Böden. Alpine und subalpine Nadelwälder mit Fichte und Tanne in höheren Lagen; Buche, Ahorn, Ulme und Esche in tieferen Hanglagen (z. B. Schierser Wälder mit Totholz). Mischwald-reicher Talkessel mit feuchten, mykorrhizareichen Beständen.', ARRAY['Fichten-Steinpilz','Eierschwamm (Pfifferling)','Maronenröhrling','Trompetenpfifferling','Semmelstoppelpilz','Krause Glucke','Parasol']::text[], 'Tiefere Buchen-/Mischwälder (Schiers, Grüsch) ab Sommer für Steinpilze und Stoppelpilze; subalpine Fichten-/Tannenwälder (Küblis, Klosters) für Maronen, Eierschwämme und Trompetenpfifferlinge bis in den Herbst (ca. Juni–Oktober). Parasol auf Wiesen und Waldrändern. In Klosters werden geführte Pilzexkursionen angeboten. Graubünden: Schonzeit 1.–10., max. 2 kg/Tag. Jeden Fund vor dem Verzehr von der VAPKO-Pilzkontrolle prüfen lassen.', 'Rätikon mit Kalk-Felswänden nahe 3000 m; Verstanclahorn als höchster Gipfel; Skiort Klosters; Landquart als Hauptfluss.', 'en.wikipedia.org/wiki/Prättigau; de.wikipedia.org Prättigau; praettigau.info Pilze sammeln; gr.ch Artenförderung Pilze'),
('davos_landwassertal', 'Davos / Landwassertal', ARRAY['GR']::text[], 'Alpental / Hochtal', 'Hochtal um die höchstgelegene Stadt der Alpen (Davos ~1560 m), das den grössten Teil des Landwassertals umfasst. Gemeindegebiet reicht von 1051 bis 3145 m. Fraktionen Davos-Dorf, -Platz, Frauenkirch, Glaris, Monstein; Seitentäler Flüela, Dischma und Sertig.', 1051, 2300, 'Subalpine Nadelwälder; eines der grössten Bergföhren-Vorkommen der Schweiz liegt im zentralen Graubünden (Albula-/Landwassertal). Dominant Fichte, Lärche und Bergföhre auf teils kalkigem, teils saurem Untergrund. Lichte, trockene Föhren- und Lärchenhänge sowie feuchtere Fichtenbestände der Seitentäler.', ARRAY['Fichten-Steinpilz','Edelreizker','Eierschwamm (Pfifferling)','Maronenröhrling','Trompetenpfifferling','Semmelstoppelpilz']::text[], 'Hochtal — Saison spät (Hochsommer–Frühherbst, ca. Juli–Oktober). Bergföhren-/Lärchenhänge für Edelreizker, feuchtere Fichtenwälder der Seitentäler (Dischma, Sertig, Monstein) für Steinpilze, Maronen und Eierschwämme. Trompetenpfifferling im moosigen Nadelwaldboden. Graubünden: Schonzeit 1.–10., max. 2 kg/Tag. Jeden Fund vor dem Verzehr von der VAPKO-Pilzkontrolle prüfen lassen.', 'Flüela Schwarzhorn (3147 m, höchster Gemeindepunkt); Davosersee; Zügenschlucht; Seitentäler Flüela, Dischma, Sertig.', 'de.wikipedia.org/wiki/Davos; en.wikipedia.org/wiki/Davos; waldwissen.net (Bergföhren Albula-/Landwassertal)'),
('albulatal', 'Albulatal', ARRAY['GR']::text[], 'Tal', 'Rund 20 km langes Tal der Albula vom Albulapass bis zur Schinschlucht, Teil der Kulturregion Surmeir. Oberer Talboden um Bergün/Bravuogn (~1400 m), unterer Teil mit Filisur, Alvaneu Bad, Surava, Tiefencastel, Alvaschein (850–1050 m). UNESCO-Welterbe Albulabahn.', 745, 2400, 'Typischer alpiner Bergwald; Böden teils kalkhaltig, teils sauer. Dominant Fichte und Lärche, dazu Bergföhre an steilen Hängen (eines der grossen Bergföhren-Vorkommen Zentralgraubündens). Lichte Lärchen-/Föhrenhänge und dichtere Fichtenbestände entlang der Albula.', ARRAY['Fichten-Steinpilz','Edelreizker','Eierschwamm (Pfifferling)','Maronenröhrling','Trompetenpfifferling','Semmelstoppelpilz']::text[], 'Montane bis subalpine Nadelwälder; Saison Hochsommer–Herbst (ca. Juli–Oktober). Bergföhren-/Lärchenhänge um Bergün für Edelreizker, feuchtere Fichtenwälder des unteren Tals (Filisur, Alvaneu, Surava) für Steinpilze, Maronen und Eierschwämme. Graubünden: Schonzeit 1.–10., max. 2 kg/Tag. Jeden Fund vor dem Verzehr von der VAPKO-Pilzkontrolle prüfen lassen.', 'Piz Kesch (3418 m), höchster Punkt; UNESCO-Welterbe Albulabahn mit Landwasserviadukt; Schinschlucht am Talausgang.', 'de.wikipedia.org/wiki/Albulatal; en.wikipedia.org Bergün Filisur; waldwissen.net (Bergföhren)'),
('misox_val_mesolcina', 'Misox / Val Mesolcina', ARRAY['GR']::text[], 'Alpental (südalpin)', 'Italienischsprachiges Südtal Graubündens südlich des San-Bernardino-Passes, durchflossen von der Moesa. Reicht von San Vittore (~260 m) bis zum Pizzo Tambò (3279 m). Hauptorte Roveredo, Grono, Mesocco, Soazza, San Bernardino. Bei Grono wurde mit 41,5 °C die höchste je in der Schweiz gemessene Temperatur registriert.', 260, 2400, 'Südalpines/insubrisches Klima. Unten ausgedehnte Edelkastanienwälder (Selva), darüber Buchen- und Fichtenwälder, in San Bernardino subalpine Nadelwälder. Vorwiegend saure, silikatische Böden — ideal für wärmeliebende Steinpilze in Kastanien- und Buchenwald.', ARRAY['Steinpilz','Sommersteinpilz','Eierschwamm (Pfifferling)','Maronenröhrling','Trompetenpfifferling','Totentrompete','Parasol']::text[], 'Grosse Höhenspanne und warmes Südklima → lange Saison. Insubrische Kastanien-/Buchenwälder der Talstufe ab Frühsommer für Steinpilze (auch Sommersteinpilz), darüber Fichtenwälder bis San Bernardino in den Herbst (ca. Juni–November). Totentrompete und Trompetenpfifferling im feuchten Laub-/Mischwaldboden. Graubünden: Schonzeit 1.–10., max. 2 kg/Tag. Jeden Fund vor dem Verzehr von der VAPKO-Pilzkontrolle prüfen lassen.', 'Pizzo Tambò (3279 m); Bergseen Val Cama (1265 m) im höchstgelegenen Kastanienwald des Misox; angrenzendes Val Calanca; höchste je gemessene CH-Temperatur (Grono, 41,5 °C).', 'de.wikipedia.org/wiki/Misox; visit-moesano.ch; pronatura-gr.ch (Val Cama Kastanienwald); proalps.ch')
insert into public.ch_regions (slug, name, canton_codes, region_type, description, altitude_min_m, altitude_max_m, landscape, good_mushrooms, foraging_notes, highlights, source) values
('bergell_val_bregaglia', 'Bergell / Val Bregaglia', ARRAY['GR']::text[], 'Alpental (südalpin)', 'Italienischsprachiges Südtal, das in drei Stufen vom Malojapass (1815 m) abfällt: Casaccia, Vicosoprano/Stampa, dann Bondo–Castasegna (~680 m). Schweizer Teil = Gemeinde Bregaglia. Orte Maloja, Vicosoprano, Stampa, Soglio, Castasegna. Geteilt durch die Talenge ''Porta'' in Sopraporta und Sottoporta.', 680, 2400, 'Markanter Vegetationswandel: oberes Sopraporta mit subalpinen Lärchenwäldern, unteres Sottoporta bereits insubrisch mit jahrhundertealten Edelkastanienwäldern (Selva) und südalpinem Klima. Böden überwiegend silikatisch/sauer. Kastanien-, Buchen- und Lärchen-/Fichtenwald je nach Höhe.', ARRAY['Steinpilz','Sommersteinpilz','Eierschwamm (Pfifferling)','Edelreizker','Maronenröhrling','Totentrompete','Trompetenpfifferling']::text[], 'Starkes Höhen-/Klimagefälle: insubrische Kastanienwälder bei Castasegna/Soglio ab Frühsommer für Steinpilze (auch Sommersteinpilz), subalpine Lärchenwälder bei Maloja für Edelreizker und Eierschwämme bis in den Herbst (ca. Juni–Oktober). Totentrompete im feuchten Kastanien-/Buchenlaub. Graubünden: Schonzeit 1.–10., max. 2 kg/Tag. Jeden Fund vor dem Verzehr von der VAPKO-Pilzkontrolle prüfen lassen.', 'Piz Badile und Piz Cengalo (Granitgipfel über 3000 m); jahrhundertealte Kastanienwälder; Terrassendorf Soglio; Malojapass.', 'de.wikipedia.org/wiki/Bergell; en.wikipedia.org/wiki/Bregaglia; bregaglia.ch; bergell-blog.ch'),
('domleschg', 'Domleschg', ARRAY['GR']::text[], 'Tal / Hügelland', 'Breite, sonnige Talschaft auf der Ostseite des Hinterrheintals zwischen Rothenbrunnen und Thusis, gegenüber dem Heinzenberg. Talboden um 600 m, sanft ansteigende Terrassen. Orte: Thusis, Cazis, Paspels, Tomils, Scharans, Almens, Sils i.D. Eine der burgenreichsten Regionen der Schweiz (''Obstgarten Graubündens'').', 600, 1200, 'Mildes, föhnbegünstigtes Klima auf kalkbetontem Untergrund. Warm-trockene Hänge mit Eichenwald (Stieleiche/Traubeneiche) und Föhrenwald (Pionierbestände), durchsetzt mit Trockenrasen, Felsensteppen und Obstgärten. Laubwald-/Föhrenwald-Charakter bis ~1000 m, darüber Fichte/Mischwald.', ARRAY['Sommersteinpilz','Schwarzhütiger Steinpilz','Steinpilz','Parasol','Semmelstoppelpilz','Totentrompete']::text[], 'Wärmebegünstigtes Laub-/Föhrengebiet: warm-trockene Eichenwälder bringen wärmeliebende Sommersteinpilze und Schwarzhütige Steinpilze schon ab Früh-/Hochsommer; Parasol auf Magerwiesen und Waldrändern, Totentrompete im feuchteren Laubwaldboden im Herbst (ca. Juni–Oktober). Höhere Fichtenbestände am Heinzenberg ergänzen das Spektrum. Schutzgebiete/Trockenrasen beachten. Graubünden: Schonzeit 1.–10., max. 2 kg/Tag. Jeden Fund vor dem Verzehr von der VAPKO-Pilzkontrolle prüfen lassen.', 'Burgendichte (Ortenstein, Rietberg, Baldenstein, Ehrenfels u.a.); ''Obstgarten Graubündens'' mit 120 Apfel- und 30 Birnensorten; warm-trockene Eichenwälder und Felsensteppen von nationaler Bedeutung.', 'en.wikipedia.org/wiki/Domleschg_(valley); buendnerwald.ch (Eiche im Domleschg); blw.admin.ch Landschaftsqualität Domleschg/Heinzenberg; hls-dhs-dss.ch'),
('schanfigg', 'Schanfigg', ARRAY['GR']::text[], 'Tal', 'Langgestrecktes Tal östlich von Chur, das von Maladers/Passugg (~750–900 m) stetig bis zum Ferienort Arosa (~1800 m) ansteigt und sich dort zu einem Kessel weitet. Durchflossen von der Plessur. Orte: Maladers, Castiel, Lüen, St. Peter, Peist, Langwies, Tschiertschen, Arosa.', 750, 2300, 'Typische alpine Waldstaffelung: tiefere Lagen mit montanem Fichten-/Mischwald, höhere Hänge mit Lärche und Bergföhre, darüber Alpweiden. Böden teils kalkig, teils sauer. Feuchte Nadelwaldböden und lichte Lärchenhänge bieten breites Mykorrhiza-Spektrum.', ARRAY['Fichten-Steinpilz','Eierschwamm (Pfifferling)','Edelreizker','Maronenröhrling','Trompetenpfifferling','Semmelstoppelpilz']::text[], 'Stetiger Höhenanstieg: tiefere Fichten-/Mischwälder (Maladers, Castiel, Tschiertschen) ab Sommer für Steinpilze und Maronen; subalpine Lärchen-/Bergföhrenhänge Richtung Arosa für Edelreizker und Eierschwämme bis in den Herbst (ca. Juli–Oktober). Trompetenpfifferling im moosigen Nadelwaldboden. Graubünden: Schonzeit 1.–10., max. 2 kg/Tag. Jeden Fund vor dem Verzehr von der VAPKO-Pilzkontrolle prüfen lassen.', 'Ferienort Arosa (~1800 m) mit Bergseen; Langwieser Viadukt; Plessur als Hauptfluss; Schanfigger Höhenweg.', 'de.wikipedia.org/wiki/Schanfigg; arosalenzerheide.swiss; hls-dhs-dss.ch Schanfigg'),
('entlebuch', 'Entlebuch', ARRAY['LU']::text[], 'Voralpental', 'Das Entlebuch ist das rund 397 km² grosse Haupttal der Kleinen Emme zwischen Bern und Luzern im Kanton Luzern und seit 2001 UNESCO-Biosphäre. Es umfasst sieben Gemeinden, darunter Schüpfheim, Flühli, Escholzmatt-Marbach und Sörenberg. Geprägt ist die Landschaft von ausgedehnten Mooren und der Karstlandschaft der Schrattenfluh.', 600, 2350, '43% der Fläche ist Wald. Es dominieren Buchen-Tannen-, Tannen-Fichten- und reine Fichtenwälder; in den Hochmoorlagen kommen Bergföhren- und Fichten-Moorwälder vor. Geologisch wechseln kalkreiche Karstböden (Schrattenfluh, Helvetikum) mit sauren, vernässten Moor- und Flyschböden — daher eine ungewöhnlich vielfältige Standortpalette auf engem Raum.', ARRAY['Steinpilz','Eierschwamm/Pfifferling','Maronenröhrling','Trompetenpfifferling','Semmelstoppelpilz','Edelreizker','Krause Glucke','Totentrompete']::text[], 'Steinpilz, Eierschwamm und Maronenröhrling in den Fichten- und Tannen-Fichten-Wäldern der mittleren Lagen (ca. 700-1400 m), Hauptsaison Juli bis Oktober nach Niederschlag; Totentrompete und Edelreizker eher in den kalkbeeinflussten Misch- und Föhrenbeständen. Karstlagen der Schrattenfluh sind kalkreich, Moorränder sauer. Jeden Fund vor dem Verzehr zwingend bei einer offiziellen VAPKO-Pilzkontrolle prüfen lassen.', 'Höchster Gipfel ist das Brienzer Rothorn (2348 m). Über 20% aller intakten Hochmoore der Schweiz liegen im Biosphären-Perimeter. Markant sind die Karstlandschaft Schrattenfluh und das Quellgebiet der Kleinen Emme.', 'de.wikipedia.org/wiki/Entlebuch_(Region); myswitzerland.com UNESCO Biosphäre Entlebuch; parks.swiss; unesco.ch'),
('napfgebiet', 'Napfgebiet', ARRAY['LU','BE']::text[], 'Hügelland', 'Das Napfgebiet (Napfbergland) ist die rund 25 km durchmessende Hügellandschaft zwischen Bern und Luzern, deren höchster Punkt der Napf mit 1408 m ist. Eine Kantonsgrenze von Nord nach Süd teilt das Gebiet: der Westteil gehört zu Bern, der Ostteil zu Luzern. Charakteristisch sind tief eingeschnittene Gräben, schmale Grate und Einzelhof-Streusiedlung (u.a. Trub, Menzberg, Romoos).', 700, 1408, 'Das Gebiet war während der Eiszeiten eisfrei und behielt durch Wassererosion seine zerschnittene Topografie. Es besteht überwiegend aus Nagelfluh (Molasse-Konglomerat der Oberen Süsswassermolasse), dessen Verwitterung eher saure, sandig-lehmige Böden liefert. In den höheren Lagen stehen Tannen-Buchen-Wälder, in den tieferen vorwiegend Buchenwälder, durchsetzt mit Fichten und Weidewald.', ARRAY['Steinpilz','Eierschwamm/Pfifferling','Maronenröhrling','Parasol','Semmelstoppelpilz','Krause Glucke','Trompetenpfifferling']::text[], 'Steinpilz und Maronenröhrling in den Fichten-Tannen-Beständen der Höhenlagen, Eierschwamm/Pfifferling und Semmelstoppelpilz in den sauren Nagelfluh-Mischwäldern; Parasol an Waldrändern und Weideflächen der Streusiedlungen. Hauptsaison Sommer bis Spätherbst nach Regen. Krause Glucke an Nadelholz-Stöcken. Funde immer bei einer VAPKO-Pilzkontrolle prüfen lassen, bevor etwas gegessen wird.', 'Der Napf (1408 m) ist der namensgebende Gipfel. Das gesamte Napfbergland ist im Bundesinventar BLN verzeichnet; der südöstliche Teil gehört zur UNESCO-Biosphäre Entlebuch. Bekannt für die fächerförmig vom Zentralgrat ausstrahlenden Gräben (z.B. Fontannen, Grosse Fontanne) und historisches Goldwaschen.', 'de.wikipedia.org/wiki/Napfbergland; de.wikipedia.org/wiki/Napf_(Berg); napf.ch; napfgebiet.ch; trub.ch'),
('seetal', 'Seetal', ARRAY['LU','AG']::text[], 'Seeregion', 'Das Seetal ist ein Tal in den Kantonen Luzern und Aargau, das von Süden (bei Eschenbach LU) nach Norden bis Lenzburg (AG) absteigt. Es liegt im Schweizer Mittelland und beherbergt den Hallwilersee und den südlicher gelegenen Baldeggersee. Hauptorte sind u.a. Hochdorf, Hitzkirch, Seon und Lenzburg.', 400, 900, 'Eingebettet zwischen den Höhenzügen Lindenberg und Erlosen liegen die beiden Seen in einer sanften Moränenlandschaft des Mittellands. Die Hänge tragen bunte Mischwälder (Buche, Eiche, Esche, Fichte) und stattliche Hochstamm-Baumbestände. Die Böden des Mittellands sind überwiegend kalkbeeinflusst und nährstoffreich.', ARRAY['Sommersteinpilz','Eierschwamm/Pfifferling','Parasol','Totentrompete','Morchel','Maronenröhrling']::text[], 'Im Mittelland sind Laub- und Mischwälder von Lindenberg und Erlosen typisch: Sommersteinpilz und Pfifferling unter Buche und Eiche, Totentrompete in kalkreichen Laubwäldern im Spätsommer/Herbst, Parasol an Waldrändern und Wiesen, Morcheln im Frühjahr an esche-/auenreichen, kalkhaltigen Stellen. Hauptsaison später Frühling bis Herbst. Jeden Fund vor dem Verzehr zwingend bei einer VAPKO-Pilzkontrolle bestimmen lassen.', 'Der Hallwilersee (8,4 km lang, bis 47 m tief, 10,3 km²) liegt zu fünf Sechsteln im Aargau, zu einem Sechstel in Luzern. Der Baldeggersee ist seit 1940 Naturschutzgebiet und weitgehend unverbaut. Der Hallwilersee ist im BLN (1303) verzeichnet. Markant sind die Höhenzüge Lindenberg und Erlosen.', 'de.wikipedia.org/wiki/Hallwilersee; en.wikipedia.org/wiki/Seetal; seetal-luzern.ch; ag.ch BLN 1303; aargautourismus.ch'),
('muotatal', 'Muotatal', ARRAY['SZ']::text[], 'Alpental', 'Das Muotatal ist ein langes, tief eingeschnittenes Tal im Kanton Schwyz, das von der Muota durchflossen wird und unterhalb des Pragelpasses (1548 m) liegt. Die Gemeinde Muotathal umfasst rund 172 km². Weite Talflächen, steil aufragende Felsen und dicht bewaldete Hänge prägen das Bild; die Siedlungen liegen entlang des Talbodens.', 600, 2300, 'Geologisch gehört das Muotatal zu den nördlichen Kalkalpen (Helvetische Decken) — der Untergrund ist stark verkarstet. Rund 22% der Fläche ist Wald. Im verkarsteten Bödmeren-Plateau wachsen uralte Fichten, strauchförmige Moorbirken, knorrige Bergföhren neben einsamen Weisstannen und Buchen. Die Böden sind überwiegend kalkreich (Karst, Charren, Karren), mit lokal vermoorten sauren Stellen.', ARRAY['Steinpilz','Eierschwamm/Pfifferling','Trompetenpfifferling','Semmelstoppelpilz','Totentrompete','Edelreizker','Maronenröhrling']::text[], 'In den Fichten- und Tannen-Buchen-Beständen der mittleren Hanglagen Steinpilz, Eierschwamm, Trompetenpfifferling und Semmelstoppelpilz, Hauptsaison Juli bis Oktober nach Niederschlag; Totentrompete und Edelreizker im kalkreichen Karst-/Föhrenmilieu. Das Urwaldreservat Bödmeren ist geschütztes Naturreservat — dort gilt Rücksicht und ggf. Sammelverbot. Funde grundsätzlich bei einer VAPKO-Pilzkontrolle prüfen lassen, bevor sie gegessen werden.', 'Der Bödmerenwald (ca. 450-550 ha) gilt als grösster echter Fichten-Urwald der Alpen und Westeuropas — mit über 500-jährigen Fichten und mehr als 40 Flechtenarten. Direkt darunter liegt das Höhlensystem Hölloch (über 207 km erforscht, eines der grössten der Welt). Grosse Karstgebiete: Silberen, Charetalp, Pragel-Bisistal.', 'muotathal.ch Geografie/Geologie; boedmeren.ch; waldwissen.net Bödmerenwald; nzz.ch Karst Muotatal; stoos-muotatal.ch'),
('talkessel_schwyz', 'Talkessel von Schwyz (Innerschwyz)', ARRAY['SZ']::text[], 'Voralpen', 'Der Talkessel von Schwyz bildet das Herz der Region Innerschwyz, zwischen Vierwaldstättersee, Lauerzersee und Zugersee. Über dem Talboden mit dem Hauptort Schwyz und Brunnen erheben sich die markanten Mythen (Grosser Mythen 1898 m) und westlich das Rigi-Massiv. Die Region liegt im zentralen voralpinen und alpinen Raum.', 450, 1900, 'Die Hänge sind überwiegend bewaldet — die Wanderwege führen vorwiegend durch Wald hinauf zu den Höhen. Es dominieren Buchen-Tannen-Mischwälder der unteren Lagen, die nach oben in Fichten- und Bergwald übergehen. Geologisch gehört das Gebiet zu den helvetischen Kalkalpen/Voralpen — die Böden sind überwiegend kalkbeeinflusst, an den Flyschhängen lehmig-frisch.', ARRAY['Steinpilz','Sommersteinpilz','Eierschwamm/Pfifferling','Totentrompete','Semmelstoppelpilz','Parasol','Maronenröhrling']::text[], 'In den Buchen-Tannen-Mischwäldern der unteren Hanglagen Sommersteinpilz, Pfifferling und Totentrompete (kalkreiches Laubholzmilieu), in den höheren Fichtenbeständen Steinpilz, Maronenröhrling und Semmelstoppelpilz; Parasol an Wald- und Weiderändern. Hauptsaison Sommer bis Spätherbst nach Regen. Jeden Fund vor dem Essen zwingend bei einer offiziellen VAPKO-Pilzkontrolle bestimmen lassen.', 'Die zwei freistehenden Mythen (Grosser Mythen 1898 m, Kleiner Mythen) sind das Wahrzeichen und weithin erkennbar. Das Rigi-Massiv und die Mythen-Gruppe blieben während der Würm-Eiszeit eisfrei. Von der Haggenegg weiter Blick über die Talkessel von Schwyz und Brunnen mit Lauerzersee, Vierwaldstättersee und Rigi.', 'hls-dhs-dss.ch Schwyz (Kanton); schwyz-tourismus.ch; schwyzer-wanderwege.ch; bergwelten.com Mythen'),
('urner_reusstal', 'Urner Reusstal', ARRAY['UR']::text[], 'Alpental', 'Das Urner Reusstal erstreckt sich vom Urnersee (südöstlicher Arm des Vierwaldstättersees) bis zur Schöllenen und wird grob in das untere und obere Reusstal geteilt. Im unteren Reusstal um den Hauptort Altdorf (knapp 10''000 Einwohner) lebt rund 80% der Urner Bevölkerung; das obere Reusstal reicht von Erstfeld bis Göschenen. Weitere Orte: Bürglen, Schattdorf, Erstfeld.', 440, 2000, 'Der flache Talboden trägt Reuss, Wiesen und Auen; die steilen Talflanken sind dicht bewaldet — Fichten-Tannen-Bergwald über kollinen Laub-/Mischwäldern. Das Gebiet liegt im Bereich der kristallinen Zentralalpen (Aaremassiv), die Böden der Hänge sind überwiegend sauer und silikatisch, im Talgrund alluvial. Alpine Zonen liegen in den Seitentälern (Erstfeldertal, Maderanertal, Meiental).', ARRAY['Steinpilz','Eierschwamm/Pfifferling','Maronenröhrling','Trompetenpfifferling','Edelreizker','Semmelstoppelpilz','Krause Glucke']::text[], 'In den sauren Fichten- und Tannen-Fichten-Bergwäldern der Talflanken und Seitentäler Steinpilz, Maronenröhrling, Eierschwamm und Trompetenpfifferling, Hauptsaison Juli bis Oktober nach Niederschlag; Edelreizker unter Fichte/Föhre, Krause Glucke an Nadelholz-Stöcken. In den tieferen Laubwäldern des Talbodens auch Sommersteinpilz. Jeden Fund vor dem Verzehr zwingend bei einer VAPKO-Pilzkontrolle prüfen lassen.', 'Altdorf mit dem Tell-Denkmal ist das Zentrum. Die Haldi-Hochterrasse (1100-1200 m) bildet den Übergang von der Reussebene ins Schächental. Der Urnersee und die steilen Reussflanken prägen das Bild; markant der Übergang zur Schöllenen-Schlucht Richtung Gotthard.', 'hls-dhs-dss.ch Uri; urneralpen.ch oberes/unteres Reusstal; ur.ch Gemeinden; lds.geo.uzh.ch Urnersee Geologie'),
('sarneraatal', 'Sarneraatal', ARRAY['OW']::text[], 'Voralpental', 'Das Sarneraatal ist das Haupttal des Kantons Obwalden in der Zentralschweiz und erstreckt sich rund 30 km vom Brünigpass (1008 m) Richtung Nordosten bis zum Alpnachersee (434 m). Es ist gestuft: nach dem Lungerersee folgt bei Kaiserstuhl der Abfall zum eigentlichen Talboden ab Giswil (484 m). Hauptorte: Lungern, Giswil, Sachseln, Sarnen, Kägiswil, Alpnach.', 434, 1700, 'Der grösste Teil gehört zu den Unterwaldner Voralpen (Teil der Zentralschweizer Voralpen). An der östlichen Talflanke prägt sanftes Flyschgelände das Bild, die Westseite zeigt steilere voralpine Rücken. Es überwiegen Buchen-Tannen- und Fichten-Tannen-Wälder; die Flyschböden sind frisch-lehmig und eher basenreich, in höheren Lagen kalkbeeinflusst.', ARRAY['Steinpilz','Sommersteinpilz','Eierschwamm/Pfifferling','Trompetenpfifferling','Totentrompete','Semmelstoppelpilz','Maronenröhrling']::text[], 'In den Buchen-Tannen- und Fichten-Tannen-Wäldern der Flyschhänge Sommersteinpilz, Eierschwamm, Trompetenpfifferling und Totentrompete; in den höheren Fichtenbeständen Steinpilz, Maronenröhrling und Semmelstoppelpilz. Hauptsaison Juli bis Oktober nach Niederschlag, im Laubwald auch früher. Jeden Fund vor dem Essen zwingend bei einer offiziellen VAPKO-Pilzkontrolle bestimmen lassen.', 'Drei Seen prägen das Tal: Lungerersee, Sarnersee und Wichelsee, mit Übergang zum Alpnachersee am Vierwaldstättersee. An der östlichen Talflanke liegt auf der Älggi-Alp der geografische Mittelpunkt der Schweiz. Der Brünigpass (1008 m) bildet die Südgrenze.', 'de.wikipedia.org/wiki/Sarneraatal; de.wikipedia.org/wiki/Kanton_Obwalden; obwalden-tourismus.ch; gemeinde-schweiz.ch Sarnen'),
('engelbergertal', 'Engelbergertal', ARRAY['OW','NW','UR']::text[], 'Alpental', 'Das Engelbergertal ist ein rund 25 km langes Tal in der Zentralschweiz, das sich über die Kantone Obwalden, Nidwalden und Uri erstreckt und von der Engelberger Aa entwässert wird. Vom Surenenpass (2292 m) führt das Surenental hinab nach Engelberg (1000 m); von dort verläuft das Tal nordwärts zum Stanser Boden (455 m). Orte: Engelberg, Grafenort, Wolfenschiessen, Dallenwil, Stans.', 455, 2300, 'Engelberg liegt in einem flachen, weiten Hochtal auf ca. 1000 m, eingeschlossen zwischen dem 3238 m hohen Titlis im Süden und einer Bergkette bis ca. 2800 m im Norden. Die Talflanken tragen Fichten-Tannen-Bergwald, in tieferen Lagen Buchen-Mischwald. Geologisch dominieren helvetische Kalkalpen — die Böden sind überwiegend kalkreich, im Talboden alluvial-schottrig.', ARRAY['Steinpilz','Eierschwamm/Pfifferling','Trompetenpfifferling','Semmelstoppelpilz','Edelreizker','Totentrompete','Maronenröhrling']::text[], 'In den Fichten-Tannen-Bergwäldern der Talflanken Steinpilz, Eierschwamm, Trompetenpfifferling und Semmelstoppelpilz, Hauptsaison Juli bis Oktober nach Niederschlag; Edelreizker unter Fichte/Föhre und Totentrompete im kalkreichen Buchen-Mischwald der tieferen Lagen. Steile Hänge erfordern Vorsicht. Jeden Fund vor dem Verzehr zwingend bei einer VAPKO-Pilzkontrolle prüfen lassen.', 'Der Titlis (3238 m, mit Gletscher) überragt das Tal im Süden; im Norden Engelberger Rotstock, Ruchstock, Rigidalstock und Walenstöcke. Der flache Talboden von Engelberg entstand, als ein Bergsturz vom Titlis den Talausgang staute und der See verlandete. Das Tal wurde 2005 beim Alpenhochwasser stark getroffen.', 'de.wikipedia.org/wiki/Engelbergertal; en.wikipedia.org/wiki/Engelberg; ow-engelberg.ch; obwalden-tourismus.ch'),
('aegerital', 'Ägerital', ARRAY['ZG']::text[], 'Voralpen-Seeregion', 'Das Ägerital liegt im voralpinen Teil des Kantons Zug rund um den Ägerisee (724 m) mit den Gemeinden Oberägeri und Unterägeri (ca. 730 m). Es ist eine idyllische Moränenlandschaft, im Süden vom Ägerisee, im Norden vom Gottschalkenberg begrenzt. Der Raten (1073 m) verbindet Oberägeri mit Biberbrugg im Kanton Schwyz.', 720, 1300, 'Geprägt von Ägerisee, dichten Wäldern und steilen, bewaldeten Hängen in einer Moränenlandschaft am Übergang vom Mittelland zu den Voralpen. Es überwiegen Buchen-Tannen- und Fichten-Mischwälder; die Molasse- und Moränenböden sind teils kalkbeeinflusst, teils sauer-lehmig. Offene Wiesenlandschaften wechseln mit bewaldeten Hangzonen.', ARRAY['Steinpilz','Sommersteinpilz','Eierschwamm/Pfifferling','Trompetenpfifferling','Totentrompete','Parasol','Maronenröhrling']::text[], 'In den Buchen-Tannen- und Fichten-Mischwäldern der Hänge über dem Ägerisee Steinpilz, Eierschwamm, Trompetenpfifferling und Maronenröhrling, im kalkreichen Laubwald auch Sommersteinpilz und Totentrompete; Parasol an Wald- und Wiesenrändern. Hauptsaison Sommer bis Spätherbst nach Niederschlag. Jeden Fund vor dem Essen zwingend bei einer offiziellen VAPKO-Pilzkontrolle bestimmen lassen.', 'Der Ägerisee (724 m) ist das Zentrum. Vom Aussichtspunkt Raten reicht der Panoramablick bei klarem Wetter vom Säntis im Osten bis Pilatus und Rigi im Westen. Der Gottschalkenberg und der Höhenzug Richtung Zugerberg begrenzen das Tal; historisch bekannt durch die Schlacht am Morgarten (1315) am Südende des Sees.', 'de.wikipedia.org/wiki/Ägerisee; zug-tourismus.ch Panoramaweg Ägerital; aegerital-sattel.ch; gemeinde-schweiz.ch Unterägeri; outdooractive.com Oberägeri'),
('berner_oberland_allg', 'Berner Oberland', ARRAY['BE']::text[], 'Voralpen/Alpenregion', 'Der südliche, alpine Teil des Kantons Bern und eine der fünf Verwaltungsregionen. Er umfasst das obere Einzugsgebiet der Aare mit Thuner- und Brienzersee und reicht vom Saanenland im Westen bis zum Haslital im Osten. Wichtige Orte sind Interlaken, Thun, Spiez, Meiringen, Lauterbrunnen und Grindelwald.', 558, 4274, 'Vom Seeufer und Talboden (Buchen-Tannen-Mischwald, teils kalkhaltig) über montane Fichten-Tannen-Bergwälder bis zu subalpinen Fichten-, Lärchen- und Arvenwäldern an der Waldgrenze. Bodenchemie wechselt von kalkreich (Helvetische Kalkalpen, z.B. um Thunersee/Niesen) bis sauer auf kristallinem Untergrund im Hochgebirge (Aarmassiv).', ARRAY['Steinpilz','Eierschwamm/Pfifferling','Maronenröhrling','Trompetenpfifferling','Totentrompete','Semmelstoppelpilz','Fichtenreizker','Edelreizker','Krause Glucke','Parasol']::text[], 'Beste Zeit Spätsommer bis Oktober nach ausgiebigem Regen. In montanen Fichten-/Mischwäldern um 800-1200 m treten Steinpilze und Eierschwämme zahlreich auf; Buchenwälder am Seeufer liefern Totentrompete und Trompetenpfifferling, Föhren-/Bergföhrenbestände Edelreizker und Krause Glucke. Kantonale Schon-/Sammelregeln (BE) und mengenmäßige Limiten beachten. Jeden Fund vor dem Essen zwingend bei einer VAPKO-Pilzkontrollstelle prüfen lassen.', 'Höchster Gipfel Finsteraarhorn 4274 m (höchster des Kantons), Eiger/Mönch/Jungfrau, Thuner- und Brienzersee, UNESCO-Welterbe Jungfrau-Aletsch.', 'Wikipedia ''Bernese Oberland/Berner Oberland'', SwissFungi (waldwissen.net), AWL.ch Pilze im Berner Oberland, bern.com Tourismus'),
('haslital', 'Haslital', ARRAY['BE']::text[], 'Alpental', 'Auch Hasli oder Oberhasli genannt, der oberste Teil des Aaretals mit Seitentälern zwischen Grimselpass und Meiringen. Bildet den östlichsten Teil des Berner Oberlands am Übergang von den Voralpen zum Hochgebirge. Gemeinden: Meiringen, Innertkirchen, Gadmen, Guttannen, Hasliberg und Schattenhalb.', 564, 4274, 'Weiter grüner Talboden der Aare mit Mischwäldern, an den Hängen montane Fichten-Tannen-Bergwälder, am Hasliberg sanfte Hügel mit Weiden und Wald, oben subalpine Fichten-/Lärchenwälder. Untergrund wechselt zwischen kalkhaltigen Decken im Talbereich und saurem Grimsel-Urgestein (Granit) im hinteren Tal.', ARRAY['Steinpilz','Eierschwamm/Pfifferling','Maronenröhrling','Trompetenpfifferling','Semmelstoppelpilz','Fichtenreizker','Totentrompete','Parasol']::text[], 'September bis Oktober nach Niederschlag im montanen Bergwald um 900-1300 m am ergiebigsten (Steinpilz, Eierschwamm, Maronenröhrling unter Fichten). Auf saurem Grimsel-Granitboden eher saure Nadelwald-Arten. Bernische Sammelvorschriften beachten. Funde immer vor dem Verzehr bei einer VAPKO-Pilzkontrollstelle kontrollieren lassen.', 'Höchster Berg Finsteraarhorn 4274 m, Grimsel-Urgesteinslandschaft, Aareschlucht, Reichenbachfälle bei Meiringen.', 'Wikipedia ''Haslital'', meiringen.ch/haslital, myswitzerland.com Haslital, SwissFungi (waldwissen.net)'),
('simmental', 'Simmental', ARRAY['BE']::text[], 'Voralpental', 'Voralpental im Berner Oberland entlang der Simme. Das Obersimmental verläuft von Lenk nach Boltigen (Süd-Nord), das Niedersimmental von dort über Erlenbach und Därstetten zum Talausgang bei Wimmis/Spiez (West-Ost). Dörfer: Lenk, St. Stephan, Zweisimmen, Boltigen, Oberwil, Därstetten, Erlenbach, Diemtigen, Wimmis.', 600, 3243, 'Rund 38% Wald: montane Fichten-Tannen-Bergwälder an den Hängen, Bergahorn und Buche in tieferen Lagen, ausgedehnte Alpweiden. Helvetische Kalkketten (Stockhorn, Niesen, Gantrisch-Nähe) bedingen vielerorts kalkreiche Böden, lokal aber auch sauer.', ARRAY['Steinpilz','Eierschwamm/Pfifferling','Trompetenpfifferling','Maronenröhrling','Semmelstoppelpilz','Edelreizker','Fichtenreizker','Totentrompete','Krause Glucke']::text[], 'Spätsommer/Herbst nach Regen in den Fichten-Mischwäldern um 800-1300 m (Steinpilz, Eierschwamm). Auf kalkreichen Böden Trompetenpfifferling und Semmelstoppelpilz, in Föhrenbeständen Edelreizker/Krause Glucke. BE-Sammelregeln einhalten. Vor dem Essen jeden Fund zwingend einer VAPKO-Pilzkontrolle vorlegen.', 'Höchster Berg Wildstrubel 3243 m, Lenk am Fuß des Wildstrubel auf 1068 m, Diemtigtal als regionaler Naturpark, Simmenfälle.', 'Wikipedia ''Simmental'', HLS ''Simmental'', lenk-simmental.ch, SwissFungi (waldwissen.net)')
insert into public.ch_regions (slug, name, canton_codes, region_type, description, altitude_min_m, altitude_max_m, landscape, good_mushrooms, foraging_notes, highlights, source) values
('saanenland_gstaad', 'Saanenland / Gstaad', ARRAY['BE']::text[], 'Voralpental', 'Oberes Saanetal im äussersten Südwesten des Kantons Bern, an der Schnittstelle der Berner, Waadtländer und Freiburger Voralpen. Hauptort ist Saanen (rund 1014 m), bekanntester Ort der mondäne Ferienort Gstaad (rund 1050 m); weitere Orte Schönried, Saanenmöser, Gsteig, Lauenen.', 985, 2541, 'Charakteristischer Wechsel von offenem Wies-/Weideland und bewaldeten Hängen: montane Fichten-Tannen-Bergwälder, in tieferen Lagen Bergahorn und Buche, an den Hochlagen subalpine Fichten- und Lärchenwälder. Voralpiner Flysch- und Kalkuntergrund, Böden teils kalkreich, teils sauer.', ARRAY['Steinpilz','Eierschwamm/Pfifferling','Trompetenpfifferling','Maronenröhrling','Semmelstoppelpilz','Fichtenreizker','Edelreizker','Totentrompete']::text[], 'Herbst nach Niederschlag in den Fichten-Mischwäldern der Hanglagen um 1000-1400 m (Steinpilz, Eierschwamm, Maronenröhrling). Auf kalkhaltigem Boden Trompetenpfifferling und Semmelstoppelpilz. Kantonale Sammelvorschriften (BE) beachten. Funde grundsätzlich vor dem Verzehr bei einer VAPKO-Pilzkontrollstelle prüfen lassen.', 'Höchster Punkt Giferspitz 2541 m, tiefster Punkt 985 m an der Saane, über 120 km² Gemeindefläche Saanen, Lauenensee, über 300 km Wanderwege.', 'Wikipedia ''Saanen''/''Gstaad'', gemeinde-schweiz.ch Saanen, alpen-guide.de Gstaad-Saanenland, SwissFungi (waldwissen.net)'),
('frutigland_kandertal', 'Frutigland / Kandertal', ARRAY['BE']::text[], 'Alpental', 'Region südlich des Thunersees im westlichen Berner Oberland, im Wesentlichen das Einzugsgebiet der Kander: das Nord-Süd verlaufende Frutig- und Kandertal mit Seitentälern (Engstligental, Kiental, Gasterental u.a.). Wichtige Orte: Frutigen, Reichenbach im Kandertal, Adelboden, Kandersteg, Kandergrund.', 600, 3000, 'Trotz weitem Talboden raue Bergland-Kulisse: bewaldete Hänge mit montanen Fichten-Tannen-Bergwäldern, in tieferen Lagen Buche und Bergahorn, an den Hochlagen subalpine Fichten- und Lärchenwälder. Siedlungsterrassen an den Spissen der Niesenkette 1000-1200 m. Helvetischer Kalk- und Flyschuntergrund, Böden überwiegend kalkbeeinflusst.', ARRAY['Steinpilz','Eierschwamm/Pfifferling','Trompetenpfifferling','Maronenröhrling','Semmelstoppelpilz','Fichtenreizker','Edelreizker','Totentrompete','Krause Glucke']::text[], 'September/Oktober nach Regen in den Fichten-Mischwäldern der Hangterrassen um 1000-1400 m (Steinpilz, Eierschwamm, Maronenröhrling). Auf kalkhaltigen Böden Trompetenpfifferling und Semmelstoppelpilz, in Föhrenbeständen Edelreizker/Krause Glucke. BE-Vorschriften beachten. Vor dem Essen jeden Fund zwingend bei einer VAPKO-Pilzkontrolle prüfen lassen.', 'Niesen (2362 m) als Wahrzeichen, Oeschinensee bei Kandersteg (UNESCO-Welterbe-Perimeter), Engstligenfälle bei Adelboden, Blüemlisalp-Kette.', 'Wikipedia ''Frutigland''/''Frutigen'', adelboden-lenk-kandersteg.ch, SwissFungi (waldwissen.net)'),
('emmental', 'Emmental', ARRAY['BE']::text[], 'Hügelland', 'Sanftes, waldreiches Hügelland im mittleren Kanton Bern, gebildet aus den Becken von Emme und Ilfis. Verwaltungsregion Emmental-Oberaargau. Hauptorte: Langnau im Emmental, Burgdorf, Sumiswald, Trubschachen, Lützelflüh, Affoltern (mit der Lueg ~900 m).', 480, 1408, 'Sanfte Molasse- und Nagelfluh-Hügel mit ausgedehnten Mischwäldern: Buchen-Tannen-Fichten-Wälder, in höheren Lagen (Napfgebiet) montane Fichten-Tannen-Bergwälder. Untergrund vorwiegend Nagelfluh und Sandstein (sauer bis mässig sauer), an Bachgräben lokal kalkhaltiger Mergel.', ARRAY['Steinpilz','Eierschwamm/Pfifferling','Maronenröhrling','Trompetenpfifferling','Totentrompete','Semmelstoppelpilz','Parasol','Krause Glucke','Fichtenreizker']::text[], 'Spätsommer bis Oktober nach Regen: in den Fichten-/Mischwäldern der Hügel Steinpilz und Maronenröhrling, in Buchenwäldern Totentrompete und Trompetenpfifferling, auf Lichtungen/Weiden Parasol. Höchste Funddichte unter 1000 m. BE-Sammelregeln beachten. Funde vor dem Verzehr zwingend bei einer VAPKO-Pilzkontrollstelle prüfen lassen.', 'Napf 1408 m als höchster Punkt im Nordwesten, Aussichtspunkt Lueg bei Affoltern, tiefe Nagelfluh-Gräben und Tobel, Emmentaler Käsekultur.', 'Wikipedia ''Emmental'', HLS ''Emmental'', Wikipedia ''Napfbergland'', bern.com Emmental, SwissFungi (waldwissen.net)'),
('oberaargau', 'Oberaargau', ARRAY['BE']::text[], 'Hügelland/Mittelland', 'Nordöstlicher Teil des Kantons Bern und zentraler Teil des Mittellands, im oberen Einzugsgebiet der Aare. Erstreckt sich zwischen Napf und Jura, von Emme im Westen bis Rot und Murg im Osten. Hauptorte: Langenthal, Herzogenbuchsee, Huttwil, Niederbipp, Wangen an der Aare.', 405, 1231, 'Hügeliges Mittelland mit Feldern, Wäldern und Weihern: Buchen-Misch- und Fichtenwälder auf Molasse/Nagelfluh, am Jurasüdfuss kalkreiche Buchenwälder. Höhenrücken bis ~748 m, gegen den Napf ansteigend. Böden je nach Untergrund sauer (Nagelfluh) bis kalkhaltig (Jurarand).', ARRAY['Steinpilz','Eierschwamm/Pfifferling','Maronenröhrling','Totentrompete','Trompetenpfifferling','Semmelstoppelpilz','Parasol','Krause Glucke']::text[], 'Spätsommer/Herbst nach Regen in den Misch- und Fichtenwäldern unter ~800 m (Steinpilz, Eierschwamm, Maronenröhrling); in kalkreichen Buchenwäldern am Jurasüdfuss Totentrompete, Trompetenpfifferling und Semmelstoppelpilz. BE-Sammelvorschriften beachten. Jeden Fund vor dem Essen zwingend einer VAPKO-Pilzkontrolle vorlegen.', 'Höchster Punkt Höllchöpfli (Rumisberg) 1231 m, tiefster Punkt Aare bei Wynau 405 m, Jurasüdfuss im Norden, zahlreiche Weiher und Mischwälder.', 'Wikipedia ''Oberaargau'', HLS ''Oberaargau'', bern.com Oberaargau, SwissFungi (waldwissen.net)'),
('berner_seeland', 'Berner Seeland', ARRAY['BE','FR','NE']::text[], 'Seeregion/Mittelland', 'Flache Mittelland-Landschaft am Südostfuss des Juras rund um Bieler-, Murten- und Neuenburgersee (Drei-Seen-Land). Gehört überwiegend zum Kanton Bern, mit Anteilen der Kantone Freiburg und Neuenburg. Hauptorte: Biel/Bienne, Lyss, Aarberg, Ins, Erlach, Nidau.', 430, 600, 'Weitgehend flaches, intensiv landwirtschaftlich genutztes Tiefland (Grosses Moos) mit kleineren Waldinseln und bewaldeten Hügeln: Jolimont, Jäissberg, Büttenberg, Frienisberg und Bucheggberg. Wälder vorwiegend Buchen-Eichen-Mischwälder, an Südhängen Föhren; Molasse-Untergrund, Böden mässig sauer bis kalkhaltig.', ARRAY['Steinpilz','Eierschwamm/Pfifferling','Totentrompete','Trompetenpfifferling','Maronenröhrling','Semmelstoppelpilz','Parasol','Edelreizker']::text[], 'Spätsommer/Herbst nach Regen in den Buchen-Eichen-Mischwäldern der Hügel (Jolimont, Frienisberg, Bucheggberg): Steinpilz, Totentrompete, Trompetenpfifferling; in Föhrenbeständen an Südhängen Edelreizker. Funddichte im flachen Ackerland gering, konzentriert auf die Waldhügel. BE-Sammelregeln beachten. Funde vor dem Verzehr zwingend bei einer VAPKO-Pilzkontrolle prüfen lassen.', 'Drei-Seen-Land mit Bieler-, Murten- und Neuenburgersee, St. Petersinsel im Bielersee, Jolimont-Hügel mit Rebbau, ''Gemüsegarten der Schweiz'' im Grossen Moos, Juragewässerkorrektion.', 'Wikipedia ''Seeland (Schweiz)''/''Berner Seeland'', SAC Aufbau des Berner Seelandes, schweizer-regionen.ch, SwissFungi (waldwissen.net)'),
('schwarzenburgerland', 'Schwarzenburgerland', ARRAY['BE']::text[], 'Voralpen-Hügelland', 'Voralpine Hügelregion im Verwaltungskreis Bern-Mittelland, südwestlich von Bern auf einem Plateau zwischen Sense (Kantonsgrenze zu Freiburg) und Schwarzwasser. Hauptort Schwarzenburg (792 m); weitere Orte Guggisberg, Rüschegg, Albligen. Teil des Naturparks Gantrisch.', 600, 1200, 'Sanfte voralpine Ebenen und Hügel mit ausgedehnten Wäldern und offenen Wiesen; tiefe Sense- und Schwarzwasser-Schluchten als markante Landschaftsgrenzen. Wälder vorwiegend Buchen-Tannen-Fichten-Mischwälder, in Höhenlagen montane Fichten-Tannen-Bergwälder. Flysch- und Molasse-Untergrund, Böden teils kalkhaltig, teils sauer.', ARRAY['Steinpilz','Eierschwamm/Pfifferling','Maronenröhrling','Trompetenpfifferling','Totentrompete','Semmelstoppelpilz','Fichtenreizker','Parasol','Krause Glucke']::text[], 'Spätsommer bis Oktober nach Regen in den Buchen-Fichten-Mischwäldern um 700-1100 m (Steinpilz, Eierschwamm, Maronenröhrling); auf kalkhaltigem Boden Trompetenpfifferling, Totentrompete und Semmelstoppelpilz. Im Naturpark Gantrisch Schutzbestimmungen und BE-Sammelregeln beachten. Funde vor dem Essen zwingend bei einer VAPKO-Pilzkontrollstelle prüfen lassen.', 'Naturpark Gantrisch mit Stockhornkette, eindrückliche Sense- und Schwarzwasserschluchten, Streusiedlungen auf 600-1200 m, Längenberg und Gürbetaler Chabisland.', 'HLS ''Schwarzenburgerland'', Wikipedia ''Schwarzenburg BE'', gemeinde-schweiz.ch Schwarzenburg, Naturpark Gantrisch, SwissFungi (waldwissen.net)'),
('freiberge_franches_montagnes', 'Freiberge / Franches-Montagnes', ARRAY['JU','BE']::text[], 'Hochplateau / Voralpen-Jura', 'Rund 200 km² grosses Jura-Hochplateau im Südwesten des Kantons Jura, mit angrenzenden Teilen im Berner Jura. Erstreckt sich auf durchschnittlich 1000 m zwischen La Chaux-de-Fonds und dem Delsberger Becken. Stille, weite Landschaft aus Wytweiden, Mooren und einzeln stehenden Tannen. Hauptort Saignelégier; weitere Dörfer Le Noirmont, Les Breuleux, Montfaucon.', 950, 1185, 'Hochplateau auf Kalkuntergrund mit Karst; rund 20% Wald (überwiegend Tannen- und Fichtenwälder), rund 36% Wald- und Wytweiden mit kräftigen, einzeln oder in Gruppen stehenden Fichten. Reste des ursprünglichen Buchen-Tannen-Waldes. Lehm- und Mergeldecken in Senken schaffen Flach- und Hochmoore. Insgesamt kalkdominiert, lokal saure Moorböden.', ARRAY['Steinpilz','Eierschwamm/Pfifferling','Maronenröhrling','Trompetenpfifferling','Semmelstoppelpilz','Edelreizker','Krause Glucke']::text[], 'Hauptsaison Spätsommer bis Herbst (Aug–Okt) in den Tannen-Fichten-Wäldern und an den Rändern der Wytweiden auf 950–1100 m; Steinpilz und Pfifferling im Nadel-/Mischwald, Trompetenpfifferling und Totentrompete in feuchteren, moosigen Lagen. Wegen der Höhe oft etwas spätere Saison als im Mittelland. Funde sind eine reine Vorkommens-Einschätzung nach Waldtyp/Höhe und KEINE Essbarkeits-Freigabe — jeden Fund vor dem Verzehr zwingend bei einer VAPKO-Pilzkontrollstelle prüfen lassen.', 'Höchster Punkt um 1185 m. Moorseen Étang de la Gruère und Étang des Royes, ausgedehnte Hoch- und Flachmoore (BLN-Gebiet), bekannt für Freiberger Pferde und Käse.', 'Wikipedia ''Freiberge'', Wikipedia ''Franches-Montagnes (BLN)'', myswitzerland.com, HLS'),
('delsberger_becken_val_terbi', 'Delsberger Becken / Val Terbi', ARRAY['JU']::text[], 'Talbecken / Faltenjura', 'Breites, rund 24 km langes Talbecken im Faltenjura des Kantons Jura, west-östlich orientiert, max. ca. 5 km breit bei Delémont. Talboden durchgehend 400–500 m. Gegliedert in drei Teilbecken; das östliche um Courchapoix bis Mervelier heisst Val Terbi. Hauptort Delémont (Delsberg), weitere Dörfer Glovelier, Bassecourt, Courroux, Vicques.', 400, 1100, 'Breite Synklinale im Faltenjura mit tertiären Sandstein- und Mergelablagerungen im Talgrund (eher neutral), umrahmt von Kalkrippen (oberer Jura) an den bewaldeten Hängen. Rund 43% der Fläche von Delémont sind Wald — Buchen- und Buchen-Tannen-Mischwälder an den Hangflanken. Mischung aus kalkreichen Hängen und neutralen Talböden.', ARRAY['Steinpilz','Eierschwamm/Pfifferling','Maronenröhrling','Parasol','Totentrompete','Semmelstoppelpilz','Edelreizker']::text[], 'Bewaldete Hangflanken (Buchen-Tannen-Mischwald) sind die ergiebigsten Lagen, Saison Spätsommer bis Herbst (Aug–Nov). Steinpilz und Pfifferling im Buchen-/Mischwald, Totentrompete und Semmelstoppelpilz im Buchen-Laub, Parasol an Waldrändern und Wytweiden. Talboden eher agrarisch und weniger interessant. Funde sind eine habitat-basierte Vorkommens-Einschätzung, KEINE Essbarkeits-Freigabe — jeden Fund vor dem Verzehr zwingend bei einer VAPKO-Pilzkontrollstelle prüfen lassen.', 'Umrahmt von Mont Russelin (951 m), Les Ordons (995 m), Grand Mont (1073 m) und Mont Raimeux (1302 m). Flüsse Sorne, Birs und Scheulte.', 'Wikipedia ''Delsberger Becken'', Wikipedia ''Delsberg'', Wikivoyage Jura'),
('laufental', 'Laufental (Laufenbecken)', ARRAY['BL']::text[], 'Talbecken / Faltenjura', 'Rund 90 km² grosser Bezirk Laufen im Süden des Kantons Basel-Landschaft, eine im Kanton einzigartige Beckenlandschaft. Umfasst Birs- und Lützeltal sowie das Laufenbecken und grenzt an die Kantone Jura und Solothurn sowie an Frankreich. Hauptort Laufen; weitere Dörfer Zwingen, Röschenz, Liesberg.', 293, 865, 'Faltenjura-Landschaft aus Jurakalk mit Karst; das Becken ist weitgehend gerodet, sanfte Höhenrücken und Talmulden. Kalkdominierte Böden. Nordhänge produktive Nutzwälder (Fichte/Tanne), Südhänge naturschutz-betonte Kalk-Buchenwälder. Durchflossen von Birs und Lützel.', ARRAY['Steinpilz','Eierschwamm/Pfifferling','Maronenröhrling','Totentrompete','Semmelstoppelpilz','Parasol','Morchel']::text[], 'Bewaldete Hänge des Beckens — Kalk-Buchenwald auf Südseiten, Fichten-/Tannen-Forste auf Nordseiten — von Spätsommer bis Herbst (Aug–Okt); Morcheln im Frühjahr (April–Mai) in kalkreichen Auen-/Eschenlagen entlang Birs und Lützel. Steinpilz und Pfifferling im Mischwald, Totentrompete und Semmelstoppelpilz im Buchen-Laub. Funde sind eine Vorkommens-Einschätzung nach Waldtyp, KEINE Essbarkeits-Freigabe — jeden Fund vor dem Verzehr zwingend bei einer VAPKO-Pilzkontrollstelle prüfen lassen.', 'Höchster Punkt Blauen-Kette (bis ca. 865 m im Bezirk). Karstformen, Klusen entlang der Birs. Grenze zu Frankreich im Westen.', 'Wikipedia ''Bezirk Laufen'', regionatur.ch Laufenbecken, geschichte.bl.ch, Amt für Wald beider Basel'),
('schwarzbubenland', 'Schwarzbubenland (Dorneck-Thierstein)', ARRAY['SO']::text[], 'Hügelland / Faltenjura', 'Nördlichster Teil des Kantons Solothurn, bestehend aus den Bezirken Dorneck und Thierstein (Amtei Dorneck-Thierstein), vollständig im Juragebirge. Grenzt an Basel-Landschaft, Bern, Jura und Frankreich. Von Tälern, Klusen und Schluchten geprägt. Wichtige Dörfer Breitenbach, Nunningen, Dornach, Büren.', 300, 1205, 'Typische Jura-Kalk-Landschaft mit Buchenwäldern und Tannen-Buchen-Wäldern auf Kalkböden, vielen alten Bäumen. Hügelketten, Klusen und Schluchten schaffen vielfältige Mikrohabitate. Charakteristisch sind Kirschbäume, Wälder und Wiesen. Kalkdominiert.', ARRAY['Steinpilz','Eierschwamm/Pfifferling','Totentrompete','Trompetenpfifferling','Semmelstoppelpilz','Maronenröhrling','Parasol','Edelreizker']::text[], 'Die Kalk-Buchen- und Tannen-Buchen-Wälder sind klassisches Steinpilz- und Pfifferling-Terrain, Hauptsaison Spätsommer bis Herbst (Aug–Nov). Totentrompete und Trompetenpfifferling in moosig-feuchten Buchen-Lagen, Semmelstoppelpilz im Laub, Edelreizker in den höheren Föhren-/Fichten-Anteilen am Passwang und der Hohen Winde. Funde sind eine habitat-basierte Vorkommens-Einschätzung, KEINE Essbarkeits-Freigabe — jeden Fund vor dem Verzehr zwingend bei einer VAPKO-Pilzkontrollstelle prüfen lassen.', 'Hohe Winde (1205 m), Passwang/Vogelberg (1204 m), Blauen (837 m), Gempenplateau mit Scharten (760 m), Riedberg bei Nunningen (943 m). Auf dem nahen Bettlachstock über-200-jährige Buchen (Teil des UNESCO-Buchenwald-Erbes der Region).', 'Wikipedia ''Schwarzbubenland'', HLS, Kanton Solothurn Tourismus, SRF (UNESCO-Buchenwälder)'),
('solothurner_jura_thal', 'Solothurner Jura / Thal (Naturpark Thal)', ARRAY['SO']::text[], 'Alpental / Faltenjura (Ketteljura)', 'Bezirk Thal im Kanton Solothurn, deckungsgleich mit dem Regionalen Naturpark Thal — eine sanfte Landschaft des östlichen Ketteljuras. Umfasst Balsthal, Welschenrohr-Gänsbrunnen, Herbetswil, Aedermannsdorf, Matzendorf, Laupersdorf, Mümliswil-Ramiswil und Holderbank. Geprägt von Klusen und der zweiten Jurakette.', 500, 1445, 'Ketteljura auf Kalk mit verschiedenen Waldtypen: Buchenwälder, Tannen-Buchen-Wälder und Föhrenwälder (Kiefer). Extensive Weidewirtschaft auf den Jurahöhen mit wertvollen Trockenwiesen. Kalkdominierte Böden, Klusen und Schluchten als Sonderhabitate.', ARRAY['Steinpilz','Eierschwamm/Pfifferling','Maronenröhrling','Edelreizker','Trompetenpfifferling','Totentrompete','Semmelstoppelpilz','Krause Glucke']::text[], 'Buchen- und Tannen-Buchen-Wälder der Talflanken sowie Föhrenwälder liefern von Spätsommer bis Herbst (Aug–Nov) Steinpilz, Pfifferling und Maronenröhrling; Edelreizker und Krause Glucke (an Föhren/Kiefer) in den Föhrenwäldern; Totentrompete in feuchten Buchen-Lagen. Höhere Lagen mit etwas späterer Saison. Funde sind eine Vorkommens-Einschätzung nach Waldtyp/Höhe, KEINE Essbarkeits-Freigabe — jeden Fund vor dem Verzehr zwingend bei einer VAPKO-Pilzkontrollstelle prüfen lassen.', 'Höchste Erhebungen Richtung Hasenmatt/Röti und der Weissenstein-Kette (bis ~1445 m am Übergang). Jura-Höhenweg-Etappe Balsthal–Weissenstein. Klusen, Wolfsschlucht, Höllchöpfli.', 'Wikipedia ''Regionaler Naturpark Thal'', naturparkthal.ch, parks.swiss, Kanton Solothurn Tourismus'),
('baselbieter_jura', 'Baselbieter Jura (Tafel- und Faltenjura)', ARRAY['BL']::text[], 'Hügelland / Tafeljura & Faltenjura', 'Der jurassische Teil des Kantons Basel-Landschaft, geologisch gegliedert in Tafeljura (rund halbes Kantonsgebiet, tafelartige Hochflächen) und Faltenjura (südliche Ketten). Sanftes, abwechslungsreiches Hügelland von der collinen bis zur montanen Stufe. Zahlreiche Dörfer im Ergolztal und in den Seitentälern (Liestal-Umfeld, Sissach, Waldenburg).', 270, 1169, 'Tafeljura aus Muschelkalk, Hauptrogenstein und Malmkalk (kalkdominiert) mit tafelartigen Hochflächen und steilwandigen Tälern; grosse Teile als Buchen-Mischwald und Kulturland. Hochstamm-Obstgärten und artenreiche Wiesen. Im Faltenjura höhere Ketten über Passwang, Belchen bis Geissflue. Buchen-, Eichen- und Föhrenbestände.', ARRAY['Steinpilz','Eierschwamm/Pfifferling','Maronenröhrling','Totentrompete','Semmelstoppelpilz','Parasol','Edelreizker','Krause Glucke']::text[], 'Buchen-Mischwälder des Tafel- und Faltenjuras von Spätsommer bis Herbst (Aug–Nov); Steinpilz und Pfifferling im Buchen-/Mischwald, Totentrompete und Semmelstoppelpilz im Buchen-Laub, Parasol an Waldrändern und in Hochstamm-Obstgärten, Edelreizker und Krause Glucke in den Föhren-/Fichten-Anteilen der höheren Faltenjura-Ketten. Funde sind eine habitat-basierte Vorkommens-Einschätzung, KEINE Essbarkeits-Freigabe — jeden Fund vor dem Verzehr zwingend bei einer VAPKO-Pilzkontrollstelle prüfen lassen.', 'Höchste Lagen im Faltenjura: Passwang (1204 m), Belchen (1123 m), Geissflue (963 m). Im Tafeljura geringere Höhenunterschiede, Plateaus um Sissach/Gempen. Tafeljura-Landschaft ist anerkanntes BirdLife-IBA.', 'Wikipedia ''Tafeljura'', regionatur.ch (Tafeljura/Kettenjura), baselland.ch Geologie, BirdLife IBA 003'),
('fricktal', 'Fricktal', ARRAY['AG']::text[], 'Tafeljura / Talregion', 'Die Bezirke Laufenburg und Rheinfelden im Norden des Kantons Aargau, eine Tafeljura-Landschaft zwischen Rhein und Ketteljura. Zahlreiche nordgerichtete Täler entwässern über die Sissle oder direkt in den Rhein. Hauptorte Frick (im Sissle-Tal um 350 m), Rheinfelden, Laufenburg, Möhlin.', 270, 866, 'Tafeljura aus Muschelkalk, Hauptrogenstein und Malmkalk (kalkdominiert) mit waldreichen Höhenrücken als Reste der einstigen Hochfläche; dazu zehn kleine Seitentäler und die Rhein-Auen. Wald vor allem auf den steileren Hängen — Buchen-Mischwälder, Eichen- und Föhrenbestände; Löss-Ebenen (z. B. Möhlin) im Talgrund.', ARRAY['Steinpilz','Eierschwamm/Pfifferling','Maronenröhrling','Totentrompete','Semmelstoppelpilz','Parasol','Morchel']::text[], 'Bewaldete Tafeljura-Höhenrücken (Buchen-/Eichen-/Föhren-Mischwald) von Spätsommer bis Herbst (Aug–Nov) für Steinpilz, Pfifferling, Maronenröhrling und Totentrompete; Morcheln im Frühjahr (April–Mai) in den kalkreichen Rhein-Auen und Löss-Lagen. Parasol an Waldrändern und Wiesen. Funde sind eine Vorkommens-Einschätzung nach Waldtyp, KEINE Essbarkeits-Freigabe — jeden Fund vor dem Verzehr zwingend bei einer VAPKO-Pilzkontrollstelle prüfen lassen.', 'Hohwacht bei Leibstadt (462 m) und Tafeljura-Höhen bis gegen 866 m. Rhein-Auen als Sonderhabitat. Fricktaler Höhenweg über die bewaldeten Rücken.', 'HLS ''Fricktal'', Wikipedia ''Frick'', Wikipedia ''Tafeljura'', tourismus-rheinfelden.ch'),
('vallee_de_joux', 'Vallée de Joux', ARRAY['VD']::text[], 'Hochtal / Faltenjura (Haut-Jura vaudois)', 'Hochtal auf rund 1000 m im Waadtländer Jura (Jura vaudois), am nordwestlichen Ende der Schweiz an der Grenze zu Frankreich. Erstreckt sich rund 46 km zwischen Vallorbe und La Cure. Im Tal liegt der Lac de Joux, der grösste See des Juras. Hauptorte Le Sentier, Le Brassus, L''Abbaye, Le Pont. Teil des Parc naturel régional Jura vaudois.', 1000, 1679, 'Verkarstetes Kalkgebirge; heute überwiegend bewaldet. Hochlagen-Fichten- und Tannenwälder, der Grand Risoux im Nordwesten ist das grösste zusammenhängende Waldgebiet des Juras (dichter, kaum gerodeter Nadelwald). Subalpine/montane Fichtenwälder an den Osthängen. Kalk mit ausgedehnten Hochmooren (rund 300 ha Feuchtgebiete).', ARRAY['Steinpilz','Eierschwamm/Pfifferling','Maronenröhrling','Edelreizker','Trompetenpfifferling','Semmelstoppelpilz','Krause Glucke']::text[], 'Montan-subalpine Fichten-/Tannenwälder (Grand Risoux, Osthänge) von Spätsommer bis Herbst (Aug–Okt, höhenbedingt eher kurz); Steinpilz (Fichten-Steinpilz), Maronenröhrling, Edelreizker und Krause Glucke sind typische Nadelwald-Arten dieser Höhe, Pfifferling und Trompetenpfifferling in moosigen Lagen. Wegen der Höhe um 1000–1400 m später Saisonbeginn und früheres Ende als im Mittelland. Funde sind eine habitat-basierte Vorkommens-Einschätzung im Bergnadelwald, KEINE Essbarkeits-Freigabe — jeden Fund vor dem Verzehr zwingend bei einer VAPKO-Pilzkontrollstelle prüfen lassen.', 'Mont Tendre (1679 m) — höchster Gipfel des Schweizer Juras — im Südosten; Risoux über 1400 m im Nordwesten. Lac de Joux (9,5 km²), grösster Jurasee. National bedeutende Hoch- und Flachmoore.', 'Wikipedia ''Vallée de Joux et Haut-Jura vaudois'', myvalleedejoux.ch, vaud.ch, quaeldich.de'),
('greyerzbezirk_gruyere', 'Greyerzbezirk (La Gruyère)', ARRAY['FR']::text[], 'Voralpen', 'Der Greyerzbezirk (frz. La Gruyère) ist einer der sieben Bezirke des Kantons Freiburg und liegt in den Freiburger Voralpen entlang der Saane. Hauptort ist Bulle; bekannte Ortschaften sind Gruyères, Broc, Charmey und Riaz. Die Landschaft ist gepragt von saftigen Alpweiden, bewaldeten Hoehenzuegen und markanten Gipfeln wie dem Moleson. Ein Grossteil gehoert zum Regionalen Naturpark Gruyere Pays-d''Enhaut.', 608, 2389, 'Voralpenlandschaft mit Mischung aus Buchen-Tannen-Mischwald in mittleren Lagen und Fichtenwald (Bergwald) hoeher hinauf, dazwischen Alpweiden. Boeden teils kalkreich (Voralpen-Flysch/Kalk), teils saurer auf Sandstein. Steile Talflanken bewaldet, Talboden um 700-800 m.', ARRAY['Steinpilz','Eierschwamm (Pfifferling)','Maronenroehrling','Trompetenpfifferling','Totentrompete','Semmelstoppelpilz','Parasol','Krause Glucke','Edelreizker']::text[], 'Pilzsaison vor allem August bis Oktober: Steinpilz und Eierschwamm im Buchen-Tannen-Mischwald der mittleren Lagen (800-1300 m), Maronen- und Trompetenpfifferling im saureren Fichtenwald hoeher hinauf, Edelreizker bei Foehren/Fichten auf Kalk. Jeder Fund muss VOR dem Verzehr von einer offiziellen VAPKO-Pilzkontrollstelle geprueft werden.', 'Hoechster Punkt im Bezirksgebiet ca. 2389 m; Moleson als Hausberg; Saane (Sarine) als Hauptfluss; Greyerzersee (Lac de la Gruyere) als grosser Stausee; Regionaler Naturpark Gruyere Pays-d''Enhaut.', 'de.wikipedia.org/wiki/Greyerzbezirk (Hoehe 608-2389 m); de.wikipedia.org/wiki/Greyerz_FR; regiongruyere.ch; bergwelten.com (Greyerzer Voralpen); myswitzerland.com Region Fribourg')
insert into public.ch_regions (slug, name, canton_codes, region_type, description, altitude_min_m, altitude_max_m, landscape, good_mushrooms, foraging_notes, highlights, source) values
('sensebezirk', 'Sensebezirk', ARRAY['FR']::text[], 'Voralpen', 'Der Sensebezirk ist der deutschsprachige Bezirk im Nordosten des Kantons Freiburg, zweitgroesster Bezirk des Kantons. Er reicht vom Mittelland-Huegelland bis in die Freiburger Voralpen. Bekannte Orte sind Tafers (Hauptort), Plaffeien, Schmitten und das Tourismusgebiet Schwarzsee (Lac Noir). Das Senseoberland liegt huegelig in den Voralpen, durchzogen von Sense und Aergera.', 486, 2234, 'Vom Mittelland-Buchenmischwald (tiefe Lagen an der Saane) bis zum voralpinen Buchen-Tannen- und Fichten-Bergwald im Senseoberland. Boeden gemischt: kalkreich in den Voralpen, saurer auf Molasse-Sandstein im Huegelland. Steile, bewaldete Taeler von Sense und Aergera.', ARRAY['Steinpilz','Eierschwamm (Pfifferling)','Maronenroehrling','Trompetenpfifferling','Totentrompete','Semmelstoppelpilz','Parasol','Krause Glucke']::text[], 'Sammelzeit Spaetsommer bis Herbst: Steinpilz und Eierschwamm im Buchen-Tannen-Mischwald des Senseoberlandes (800-1300 m), Maronenroehrling und Trompetenpfifferling im Fichten-Bergwald hoeher hinauf, im Mittelland-Huegelland Parasol an Waldraendern und Wiesen. Saemtliche Funde sind VOR dem Verzehr bei einer VAPKO-Pilzkontrollstelle abzuklaeren.', 'Hoechster Punkt Schafberg 2234 m; tiefster Punkt Saane unterhalb Boesingen ca. 486 m; Schwarzsee (Lac Noir) auf 1046 m als Bergsee; Senseoberland in den Freiburger Voralpen.', 'de.wikipedia.org/wiki/Schwarzsee_(See_im_Kanton_Freiburg); de.wikipedia.org/wiki/Senseoberland; fribourg.ch Schwarzsee-Senseland (Hoehen Schafberg 2234 m / Saane 486 m); bergwelten.com Freiburger Voralpen'),
('vivisbachbezirk_veveyse', 'Vivisbachbezirk (Veveyse)', ARRAY['FR']::text[], 'Voralpen', 'Der Vivisbachbezirk (frz. District de la Veveyse) ist der suedlichste Bezirk des Kantons Freiburg, noerdlich von Vevey gelegen. Hauptort ist Chatel-Saint-Denis am Fuss der Freiburger Voralpen. Die Landschaft umfasst hoeheres Freiburger Mittelland und angrenzende Voralpen mit bewaldeten Huegeln, Bergseen und Naturschutzgebieten.', 700, 1630, 'Hoeheres Freiburger Mittelland mit Buchen-Tannen-Mischwald, uebergehend in voralpinen Fichten-Bergwald. Bewaldete Huegel (z.B. Barlattey 1630 m), Boeden teils kalkreich (Voralpen), teils saurer Molasse. Bergseen wie Lac des Joncs mit Naturschutzgebiet.', ARRAY['Steinpilz','Eierschwamm (Pfifferling)','Maronenroehrling','Trompetenpfifferling','Totentrompete','Semmelstoppelpilz','Parasol']::text[], 'Pilze von Spaetsommer bis Herbst: Steinpilz und Eierschwamm im Buchen-Tannen-Mischwald der Mittellandhoehen, Maronen- und Trompetenpfifferling im Fichtenwald der Voralpenhuegel, Parasol an Waldraendern. Jeder gesammelte Pilz muss VOR dem Essen von einer offiziellen VAPKO-Pilzkontrolle freigegeben werden.', 'Bezirkshoehe um 842 m (Hauptort Chatel-St-Denis 809 m); Corbetta 1401 m mit Bergsee und Naturschutzgebiet Lac des Joncs; bewaldeter Huegel Barlattey 1630 m; am Fuss der Freiburger Voralpen.', 'de.wikipedia.org/wiki/Vivisbachbezirk (842 m); de.wikipedia.org/wiki/Ch%C3%A2tel-St-Denis (809 m, Corbetta 1401 m, Barlattey 1630 m, Lac des Joncs); en.wikipedia.org/wiki/Veveyse_(district)'),
('gros_de_vaud', 'Gros-de-Vaud', ARRAY['VD']::text[], 'Huegelland', 'Das Gros-de-Vaud ist ein leicht gewelltes Plateau- und Huegelland im Zentrum des Kantons Waadt, oft als Kornkammer des Kantons bezeichnet. Hauptort ist Echallens. Die fruchtbare, eher trockene Landschaft wird von Getreide-, Raps- und Maisfeldern gepraegt, durchsetzt von Laub- und Mischwaeldern und kleinen Tobeln.', 500, 700, 'Sanft gewelltes Mittelland-Plateau (im Schnitt 550-600 m) mit fruchtbaren Molasse-Boeden. Wald als Buchen-Eichen-Laubmischwald und Fichten-Tannen-Bestaende auf den Kuppen und in den Bachtobeln; relativ trockenes Klima. Naehe zum grossen Jorat-Waldgebiet.', ARRAY['Steinpilz','Eierschwamm (Pfifferling)','Maronenroehrling','Parasol','Semmelstoppelpilz','Totentrompete']::text[], 'Im Mittelland eher spaeter Sommer bis Herbst: Steinpilz und Eierschwamm in den Buchen-Mischwaeldern und Fichtenbestaenden der Waldinseln, Parasol auf Wiesen und an Waldraendern, Maronen im sauren Nadelwald. Wegen des trockenen Klimas sind feuchte Tobel ergiebiger. Alle Funde sind VOR dem Verzehr bei einer VAPKO-Pilzkontrollstelle pruefen zu lassen.', 'Durchschnittshoehe 550-600 m; Echallens als Hauptort und Agrarzentrum; Kornkammer des Kantons Waadt; Naehe zum Jorat, dem groessten zusammenhaengenden Waldgebiet des Schweizer Mittellandes.', 'en.wikipedia.org/wiki/Gros-de-Vaud (550-600 m, Kornkammer); hls-dhs-dss.ch Gros-de-Vaud; gemeinde-schweiz.ch Echallens; myvaud.ch Rundtour Gros de Vaud'),
('lavaux', 'Lavaux', ARRAY['VD']::text[], 'Seeregion', 'Das Lavaux ist das groesste zusammenhaengende Weinbaugebiet der Schweiz, an den Steilhaengen des Genfersee-Nordufers zwischen Lausanne und Vevey, im Bezirk Lavaux-Oron (Hauptort Cully). Die terrassierte Rebbau-Kulturlandschaft ist seit 2007 UNESCO-Welterbe. Oberhalb der Reben schliesst das ausgedehnte Jorat-Waldgebiet an.', 372, 930, 'Unten Rebterrassen am Genfersee (warm, trocken, kalkhaltige Molasse-Boeden), oberhalb der Reben Uebergang in das Jorat-Plateau mit Buchen-Tannen-Fichten-Mischwald, dem groessten zusammenhaengenden Wald des Schweizer Mittellandes. Sehr mildes, sonniges Seeklima an den Haengen.', ARRAY['Steinpilz','Eierschwamm (Pfifferling)','Maronenroehrling','Parasol','Totentrompete','Semmelstoppelpilz','Krause Glucke']::text[], 'Pilze nicht in den Rebbergen, sondern im Jorat-Wald oberhalb (700-930 m): Steinpilz und Eierschwamm im Buchen-Tannen-Mischwald, Maronen im Fichtenanteil, Krause Glucke an Foehren-/Fichtenstoecken. Sammelzeit Spaetsommer bis Herbst. Jeder Fund ist VOR dem Verzehr durch eine VAPKO-Pilzkontrolle freizugeben.', 'UNESCO-Welterbe seit 2007; rund 30 km Rebterrassen mit ca. 800 ha Rebflaeche und ~10''000 Terrassen; Cully als Bezirkshauptort; angrenzend der Jorat, groesster zusammenhaengender Wald des Mittellandes.', 'myswitzerland.com Lavaux; bergwelten.com UNESCO Weinberg-Terrassen Lavaux; eda.admin.ch Lavaux; sbb.ch Lavaux UNESCO-Welterbe (Jorat groesster Mittelland-Wald)'),
('pays_d_enhaut', 'Pays-d''Enhaut', ARRAY['VD']::text[], 'Alpental', 'Das Pays-d''Enhaut ist eine voralpine Talschaft im Osten des Kantons Waadt im oberen Saanetal, mit den Doerfern Chateau-d''Oex, Rossiniere und Rougemont. Es bildet den Waadtlaender Teil des Regionalen Naturparks Gruyere Pays-d''Enhaut. Charakteristisch sind Fichtenwaelder, Alpweiden und traditionelle Bergdoerfer.', 800, 2458, 'Voralpiner Charakter: Fels, Alpwiesen, Moore sowie Tannen-, Fichten- und Laubmischwaelder zwischen 800 und 2000 m. Boeden ueberwiegend kalkreich (Voralpen-Kalk). Naturreservat La Pierreuse (BLN) suedlich von Chateau-d''Oex am linken Saaneufer.', ARRAY['Steinpilz','Eierschwamm (Pfifferling)','Maronenroehrling','Trompetenpfifferling','Totentrompete','Semmelstoppelpilz','Edelreizker','Krause Glucke']::text[], 'Bergsommer bis Herbst (Juli-Oktober): Steinpilz und Eierschwamm im Buchen-Tannen-Mischwald der unteren Lagen, Maronen- und Trompetenpfifferling im Fichten-Bergwald, Edelreizker bei Fichten/Foehren auf Kalk. Im Naturreservat La Pierreuse gelten Schutzbestimmungen. Saemtliche Funde sind VOR dem Verzehr bei einer VAPKO-Pilzkontrolle pruefen zu lassen.', 'Chateau-d''Oex auf 958 m; Naturpark-Lagen zwischen 800 und 2000 m, Gipfel bis ueber 2400 m (Gummfluh-Massiv); Naturreservat La Pierreuse 34 km2 (BLN); Teil des Regionalen Naturparks Gruyere Pays-d''Enhaut.', 'de.wikipedia.org/wiki/Ch%C3%A2teau-d%E2%80%99Oex (958 m); pays-denhaut.ch; alparc.org Naturpark Gruyere Pays-d''Enhaut (800-2000 m); natur-schmetterlinge.ch Pays d''Enhaut (Tannen/Fichten/La Pierreuse BLN)'),
('chablais_vaudois', 'Chablais (vaudois/valaisan)', ARRAY['VD','VS']::text[], 'Alpental', 'Das Chablais ist die Region am unteren Rhonetal, wo die Rhone als Grenzfluss zwischen Waadt und Wallis in den Genfersee muendet. Der Schweizer Teil gliedert sich in Chablais vaudois (Bezirk Aigle mit Aigle, Bex, Ollon, Yvorne) und Chablais valaisan. Sonnige Rebhaenge am Fuss der Waadtlaender Alpen praegen das Bild.', 372, 2000, 'Talboden des unteren Rhonetals mit Reben und Auenresten, darueber bewaldete Voralpenhaenge mit Buchen-Tannen-Mischwald, hoeher Fichten-Bergwald. Boeden ueberwiegend kalkreich (Alpenkalk). Warmes, sonniges Klima im Talgrund (Yvorne, Aigle, Ollon, Bex).', ARRAY['Steinpilz','Eierschwamm (Pfifferling)','Maronenroehrling','Trompetenpfifferling','Totentrompete','Semmelstoppelpilz','Edelreizker','Parasol']::text[], 'Nicht in den Rebbergen, sondern in den bewaldeten Voralpenhaengen oberhalb: Steinpilz und Eierschwamm im Buchen-Tannen-Mischwald, Maronen- und Trompetenpfifferling im Fichtenwald, Edelreizker bei Foehren/Fichten auf Kalk. Sammelzeit Spaetsommer bis Herbst. Jeder Fund muss VOR dem Verzehr von einer VAPKO-Pilzkontrollstelle geprueft werden.', 'Aigle auf 415 m am Ostrand des unteren Rhonetals; Weinregion Chablais (~590 ha, Chasselas) mit Lagen Villeneuve, Yvorne, Aigle, Ollon, Bex; oekologische Vernetzungsprojekte im Walliser Chablais.', 'de.wikipedia.org/wiki/%C3%84len (Aigle 415 m); en.wikipedia.org/wiki/Chablais; swisswine.com / weinlandschweiz.ch Chablais; vogelwarte.ch oekologische Vernetzung Walliser Chablais; sbb.ch Wandern im Chablais'),
('jura_vaudois', 'Jura vaudois (Vallée de Joux)', ARRAY['VD']::text[], 'Jura', 'Der Jura vaudois ist der Waadtlaender Teil des Schweizer Juras mit dem Hochtal Vallee de Joux (Le Brassus, Le Sentier) und dem Parc naturel regional Jura vaudois. Pragend sind Jura-Hochketten wie Mont Tendre und Dent de Vaulion, Wytweiden (bewaldete Weiden), Trockensteinmauern und die Seen Lac de Joux und Lac Brenet.', 700, 1679, 'Karstiger Kalk-Jura mit wenig oberirdischem Wasser. Fichtenwald dominiert, daneben Laubmischwald mit Buchen, Tannen und Ahorn; typisch sind Wytweiden (lichte, bewaldete Weiden) mit Fichten und Trockensteinmauern. Boeden kalkig. Talboden Vallee de Joux um 1000 m.', ARRAY['Steinpilz','Eierschwamm (Pfifferling)','Maronenroehrling','Trompetenpfifferling','Totentrompete','Semmelstoppelpilz','Edelreizker','Krause Glucke']::text[], 'Jura-Saison Spaetsommer bis Herbst: Steinpilz und Eierschwamm im Buchen-Tannen-Mischwald und an den Raendern der Wytweiden, Maronen- und Trompetenpfifferling im Fichten-Hochwald, Edelreizker bei Fichten auf kalkigem Boden. Im BLN-Gebiet und Naturpark gelten Schutzregeln. Alle Funde sind VOR dem Verzehr bei einer VAPKO-Pilzkontrolle abzuklaeren.', 'Mont Tendre 1679 m, hoechster Punkt; Dent de Vaulion; Lac de Joux und Lac Brenet als Jura-Seen; Vallee de Joux et Haut-Jura vaudois im BLN-Inventar; Parc naturel regional Jura vaudois.', 'de.wikipedia.org/wiki/Vall%C3%A9e_de_Joux_et_Haut-Jura_vaudois (Fichtenwald, Buchen/Tannen/Ahorn, Wytweiden, Mont Tendre 1679 m, Karst-Kalk); parcjuravaudois.ch; myvalleedejoux.ch Parc Jura vaudois'),
('val_de_travers', 'Val-de-Travers', ARRAY['NE']::text[], 'Jura', 'Das Val-de-Travers ist ein Laengstal im Neuenburger Jura, durchflossen von der Areuse, mit den Doerfern Fleurier (groesster Ort) und Motiers (Verwaltungssitz). Das Tal ist die Wiege des Absinths. Es wird im Sueden und Norden von Jura-Ketten mit Gipfeln wie Chasseron (1607 m) flankiert; bekannt sind die Areuse-Schlucht und der Creux du Van.', 730, 1607, 'Kalk-Jura: Talboden um 730 m auf tertiaerem Sandstein und Mergel, steile Talflanken ueberwiegend bewaldet mit Tannen- und Buchenwald, in Hoehenlagen ausgedehnte Weiden. Hangkalk (Malm) beguenstigt kalkliebende Pilzarten. Eher kuehl-feuchtes Jura-Klima.', ARRAY['Steinpilz','Eierschwamm (Pfifferling)','Maronenroehrling','Trompetenpfifferling','Totentrompete','Semmelstoppelpilz','Edelreizker','Krause Glucke','Morchel']::text[], 'Jura-Sammelzeit Spaetsommer bis Herbst (Morcheln im Fruehling): Steinpilz und Eierschwamm im Tannen-Buchen-Mischwald der Talflanken, Maronen- und Trompetenpfifferling im Fichtenwald hoeher hinauf, Edelreizker bei Fichten auf Malm-Kalk. Im Bereich Creux du Van gelten Schutzbestimmungen. Saemtliche Funde sind VOR dem Verzehr von einer VAPKO-Pilzkontrolle freizugeben.', 'Talboden ca. 730 m; Chasseron 1607 m und Soliat 1463 m im Sueden; Creux du Van als Felszirkus mit Kalkwaenden; Areuse-Schlucht; Wiege des Absinths (Motiers).', 'de.wikipedia.org/wiki/Val_de_Travers (Talboden 730 m, Chasseron 1607 m, Tannen-/Buchenwald, Malm-Kalk, Sandstein/Mergel); j3l.ch Val-de-Travers; freizeit.ch Absinth-Weg'),
('val_de_ruz', 'Val-de-Ruz', ARRAY['NE']::text[], 'Jura', 'Das Val-de-Ruz ist ein Hochtal im Neuenburger Jura zwischen Neuenburg und La Chaux-de-Fonds, entwaessert vom Seyon Richtung Neuenburgersee. Das rund 45 km2 grosse, weite und flache Becken mit Hauptort Cernier gilt als landwirtschaftlich gepraegte Kornkammer und wird von zwei Jura-Ketten flankiert.', 700, 1400, 'Weites, flaches Hochtal-Becken (Talboden im Mittel 720 m, gegen Nordwesten bis ~900 m) im gefalteten Kalk-Jura. Poroeser Kalk lae sst Niederschlag versickern (wenig Oberflaechenwasser). Bewaldete Flankenketten mit Buchen-Tannen-Mischwald und Fichten-Hochwald, dazwischen Weiden und Ackerflaechen.', ARRAY['Steinpilz','Eierschwamm (Pfifferling)','Maronenroehrling','Trompetenpfifferling','Totentrompete','Semmelstoppelpilz','Edelreizker','Parasol']::text[], 'Sammelzeit Spaetsommer bis Herbst in den bewaldeten Jura-Flanken: Steinpilz und Eierschwamm im Buchen-Tannen-Mischwald, Maronen- und Trompetenpfifferling im Fichten-Hochwald, Edelreizker bei Fichten auf kalkigem Boden, Parasol an Waldraendern und auf Weiden. Wegen des durchlaessigen Karsts sind feuchtere Nordhaenge ergiebiger. Jeder Fund muss VOR dem Verzehr bei einer VAPKO-Pilzkontrolle geprueft werden.', 'Talboden im Mittel 720 m, gegen Nordwesten bis ~900 m; rhombisches Becken ca. 13 km lang, max. 4,5 km breit, ~45 km2; Cernier als Hauptort; gefalteter Kalk-Jura mit mehreren Kantonsgipfeln in den Flankenketten.', 'de.wikipedia.org/wiki/Val_de_Ruz (Talboden 720-900 m, ~45 km2, gefalteter Kalk-Jura, poroeser Kalk); j3l.ch Val-de-Ruz; schweizer-regionen.ch Gemeinde Val-de-Ruz'),
('goms_obergoms', 'Goms / Obergoms', ARRAY['VS']::text[], 'Alpental', 'Das Goms ist das oberste Talstück des Rhonetals im deutschsprachigen Oberwallis, ein breites, sonniges Hochtal, in dem die Rhone (Rotten) entspringt und die Pässe Furka, Grimsel und Nufenen zusammentreffen. Die Gemeinde Obergoms mit Dörfern wie Oberwald, Ulrichen und Münster prägt den hintersten Teil. Bekannt für bis zu 300 Sonnentage im Jahr, traditionelle Walliser Holzdörfer und ein dichtes Wander- und Langlaufnetz.', 1230, 2400, 'Hochalpines, sonniges Nadelwald-Tal: dominierend Fichte (Rottanne), Lärche und in höheren, montan-subalpinen Lagen Arve (Zirbe). Saure, oft podsolige Böden auf kristallinem Grundgestein (Gneis/Granit). Lichte Lärchen-Arven-Wälder an den Sonnenhängen, Fichtenbestände in tieferen und schattigeren Lagen.', ARRAY['Steinpilz','Eierschwamm','Maronenröhrling','Goldröhrling','Trompetenpfifferling','Semmelstoppelpilz']::text[], 'Pilzsaison v. a. von Ende Juli/August bis Oktober nach feuchten Phasen. Goldröhrling/Lärchenröhrling fast nur unter Lärchen; Steinpilz und Maronenröhrling in älteren Fichten- und Lärchenbeständen an Wurzelanläufen; Eierschwamm in feuchtem Moos. Höhenlagen 1300-2000 m beachten, kürzere Saison. Funde IMMER vor dem Verzehr bei einer offiziellen VAPKO-Pilzkontrolle prüfen lassen.', 'Quellgebiet der Rhone; Knotenpunkt von Furka-, Grimsel- und Nufenenpass; UNESCO-nahe alpine Hochtallandschaft; eines der bekanntesten Langlaufgebiete der Schweiz.', 'goms.ch; valais.ch/Obergoms; de.wikipedia.org Goms; waldwissen.net SwissFungi; pilzfinder.de Goldröhrling; de.wikipedia.org Gold-Röhrling'),
('loetschental', 'Lötschental', ARRAY['VS']::text[], 'Alpental', 'Das Lötschental ist ein nördliches Seitental der Rhone zwischen Visp und Gampel, eingebettet zwischen Berner und Walliser Alpen. Die Hauptdörfer Ferden, Kippel, Wiler und Blatten liegen auf 1300-1540 m, der Bahnhof Goppenstein auf 1216 m. Das Tal gilt als eines der ursprünglichsten und traditionsreichsten Täler der Alpen; ein Teil gehört zum UNESCO-Welterbe Swiss Alps Jungfrau-Aletsch.', 1200, 2200, 'Typisches zentralalpines Tal mit ausgeprägter Sonn- und Schattseite. Wälder aus Fichte und Lärche, in höheren Lagen Arve; saure kristalline Böden (Gneis). Lichte Lärchen-Arven-Wälder an den besonnten Hängen, dichtere Fichtenwälder auf der Schattseite Richtung Rhonetal.', ARRAY['Steinpilz','Eierschwamm','Maronenröhrling','Goldröhrling','Trompetenpfifferling']::text[], 'Beste Zeit August bis Oktober nach Regen, an Waldrändern und in lichten Lärchen-Fichten-Beständen der Sonn- und Schattseite (ca. 1300-2000 m). Goldröhrling unter Lärchen, Steinpilz/Maronenröhrling bei Fichten. UNESCO-/Naturschutzauflagen respektieren. Alle Funde vor dem Verzehr zwingend bei der VAPKO-Pilzkontrolle abklären lassen.', 'Höchster Berg Bietschhorn (3934 m); längstes nördliches Rhone-Seitental; UNESCO-Welterbe-Gebiet Jungfrau-Aletsch; bewahrte Tradition (Tschäggättä-Brauchtum).', 'loetschen.de geo_lage; en.wikipedia.org Lötschental; valais.ch Lötschental; waldwissen.net SwissFungi; pilzfinder.de Goldröhrling'),
('val_d_anniviers', 'Val d''Anniviers (Eifischtal)', ARRAY['VS']::text[], 'Alpental', 'Das Val d''Anniviers ist ein südliches, linksseitiges Seitental der Rhone im französischsprachigen Unterwallis, das bei Siders abzweigt. Bei Vissoie teilt es sich in das Val de Moiry und das Val de Zinal. Bekannt für seine fünf Dörfer Zinal, Grimentz, St-Luc, Chandolin und Vercorin mit alten dunklen Holzhäusern; Chandolin (1936 m) gehört zu den höchstgelegenen ganzjährig bewohnten Dörfern Europas.', 1000, 2400, 'Stark von ausgedehnten Lärchenwäldern geprägt, die im Herbst golden leuchten, mit Fichte und in Höhenlagen Arve. Saure kristalline Böden (Gneis/Granit). Lichte, sonnige Lärchen-Arven-Wälder an den Talflanken, dichtere Fichten-Mischwälder in tieferen Lagen.', ARRAY['Goldröhrling','Steinpilz','Eierschwamm','Maronenröhrling','Trompetenpfifferling','Edelreizker']::text[], 'Pilzzeit August bis Oktober. Die ausgedehnten Lärchenwälder sind klassisches Habitat für Goldröhrling/Lärchenröhrling; Steinpilz und Maronenröhrling in Fichten-Lärchen-Mischwald, Eierschwamm im feuchten Moos. Höhenbänder 1000-2000 m. Funde grundsätzlich vor dem Verzehr von der amtlichen VAPKO-Pilzkontrolle begutachten lassen.', 'Talschluss mit der ''Couronne Impériale'' (Weisshorn, Zinalrothorn, Obergabelhorn, Dent Blanche); Lac de Moiry und Moiry-Gletscher; Zinalgletscher; Chandolin als eines der höchsten Dörfer Europas.', 'de.wikipedia.org Val d''Anniviers; valdanniviers.ch; alpennavigator.de; pilzfinder.de Goldröhrling; waldwissen.net SwissFungi'),
('val_d_herens', 'Val d''Hérens (Eringertal)', ARRAY['VS']::text[], 'Alpental', 'Das Val d''Hérens (deutsch Eringertal) ist ein rund 30 km langes südliches Rhone-Seitental im französischsprachigen Wallis, das dem Bergbach Borgne von Sion bis Arolla folgt und dabei fast 1500 m Höhendifferenz überwindet. Hauptort ist Evolène (1371 m); weitere typische Dörfer sind Les Haudères und Arolla. Das Tal ist bekannt für die Erringer Kampfkühe und seine bewahrten dunklen Holzchalets.', 800, 2300, 'Eher schüttere Nadelwälder (Fichte, Lärche, in Höhenlagen Arve) wechseln mit Alpweiden; saure kristalline Böden. Lichte montane bis subalpine Lärchen-Fichten-Wälder, an den Talhängen oberhalb der Dörfer.', ARRAY['Steinpilz','Eierschwamm','Maronenröhrling','Goldröhrling','Trompetenpfifferling','Semmelstoppelpilz']::text[], 'Beste Zeit Spätsommer bis Herbst (August-Oktober) in den lichten Fichten- und Lärchenwäldern oberhalb von Evolène und Les Haudères, ca. 1000-2000 m. Goldröhrling unter Lärchen, Steinpilz/Maronenröhrling bei Fichten. Wegen schütterer Bestände gezielt Waldränder und feuchtere Mulden absuchen. Funde vor dem Essen immer bei der VAPKO-Pilzkontrolle prüfen lassen.', 'Pyramides d''Euseigne (Erdpyramiden); Dent Blanche und Arolla-Gletscherwelt; Mündung bei Sion; rund 1500 m Höhendifferenz auf 30 km.', 'de.wikipedia.org Val d''Hérens; valdherens.ch; myswitzerland.com Val d''Hérens; wegwandern.ch; waldwissen.net SwissFungi'),
('vispertaeler_mattertal', 'Vispertäler / Mattertal', ARRAY['VS']::text[], 'Alpental', 'Die Vispertäler sind die südlichen Seitentäler des Rhonetals im deutschsprachigen Oberwallis, die sich bei Stalden in das westliche Mattertal (bis Zermatt) und das östliche Saastal gabeln. Das Mattertal verläuft auf gut 25 km nord-süd von Stalden (795 m) über St. Niklaus (1120 m) und Randa (1406 m) bis Zermatt (1608 m), umgeben von zahlreichen Viertausendern inkl. Matterhorn.', 720, 2400, 'Tiefe, steile Hochgebirgstäler mit Fichten-, Lärchen- und in Höhenlagen Arvenwäldern auf sauren kristallinen Böden. Lichte, trockene Lärchen-Arven-Wälder an den besonnten Steilhängen, geschlossenere Fichtenbestände in den tieferen und schattigeren Lagen.', ARRAY['Steinpilz','Eierschwamm','Maronenröhrling','Goldröhrling','Trompetenpfifferling']::text[], 'Pilzsaison August bis Oktober in den montan-subalpinen Wäldern der Talflanken (ca. 800-2000 m). Goldröhrling unter Lärchen, Steinpilz und Maronenröhrling in älteren Fichten-/Lärchenbeständen an Wurzelanläufen, Eierschwamm in feuchtem Moos. Steiles Gelände, trittsicher unterwegs sein. Jeden Fund vor dem Verzehr von einer offiziellen VAPKO-Pilzkontrolle freigeben lassen.', 'Matterhorn (4478 m) und über 4500 m hohe Gipfel; tiefster Punkt bei Stalden (723,5 m); Gornergrat; Übergang vom Mattertal zum Saastal bei Stalden.', 'en.wikipedia.org Mattertal; randa.ch Das Mattertal; dewiki.de Vispertal; en.wikipedia.org Zermatt; waldwissen.net SwissFungi'),
('unterwallis_bas_valais', 'Unterwallis / Bas-Valais', ARRAY['VS']::text[], 'Landschaft', 'Das Unterwallis (Bas-Valais) ist der französischsprachige untere Talabschnitt der Rhone von Sierre/Sion über Martigny bis zum Chablais und zum Genfersee. Geprägt von der breiten Rhoneebene, den sonnigen Rebhängen am rechten Rhoneufer und den umrahmenden Bergketten. Wichtige Orte sind Martigny, Monthey, St-Maurice und der Talknick bei Martigny.', 400, 1500, 'Im Chablais milderes, feuchteres Klima, das Laubwälder begünstigt: Buche und Weisstanne sind häufig, in Resten der Auenwälder Stieleiche und Hagebuche; an den Hängen auch Föhren (Waldföhre) und Fichten. Böden vielfältig, im Unterwallis dominieren saure Granit-/Gneisböden, lokal kalkreichere Lagen.', ARRAY['Steinpilz','Sommersteinpilz','Parasol','Eierschwamm','Krause Glucke','Maronenröhrling']::text[], 'In den feuchteren Buchen- und Mischwäldern des Chablais und der Hanglagen v. a. von Juli/August bis November. Steinpilz und Sommersteinpilz in Buchen-/Tannenwald, Parasol auf Wiesen und Lichtungen, Krause Glucke an Föhrenstämmen, Eierschwamm im feuchten Laubmischwald. Funde vor dem Verzehr stets bei der VAPKO-Pilzkontrolle abklären lassen.', 'Talknick der Rhone bei Martigny; Chablais am Genfersee; grösstes Weinbaugebiet der Schweiz an den rechtsufrigen Sonnenhängen; Übergang vom alpinen ins voralpine, mildere Klima.', 'wikiwallis.ch Klima; de.wikipedia.org Kanton Wallis; vs.ch Bas-Valais; swisswine.com Wallis; waldwissen.net SwissFungi')
insert into public.ch_regions (slug, name, canton_codes, region_type, description, altitude_min_m, altitude_max_m, landscape, good_mushrooms, foraging_notes, highlights, source) values
('pfynwald_leuk', 'Pfynwald-Region / Leuk', ARRAY['VS']::text[], 'Seeregion', 'Der Pfynwald (Bois de Finges) liegt auf der Sprachgrenze zwischen Siders und Leuk im mittleren Rhonetal und bildet das Herz des Naturparks Pfyn-Finges. Auf dem Schwemmkegel unterhalb des Illgrabens erstreckt sich auf rund 10 km² einer der grössten zusammenhängenden Föhrenwälder Europas, durchsetzt von Rhone-Auen, Trockensteppen und kleinen Seen.', 540, 2000, 'Ausgedehnter Waldföhren-Urwald (Pinus sylvestris) als nacheiszeitliches Relikt auf trockenem, magerem Schwemmboden; einer der trockensten Orte der Schweiz (ca. 550 mm Niederschlag/Jahr). Daneben Rhone-Auenwald und heisse Steppenflächen. Karbonatreich-magere bis saure Böden, sehr lichter, warmer Kiefernwald.', ARRAY['Butterpilz','Sandröhrling','Edelreizker','Maronenröhrling','Steinpilz']::text[], 'Im trockenen Föhrenwald sind typische Kiefernbegleiter zu erwarten: Butterpilz und Sandröhrling unter Föhren, Edelreizker (Blutreizker) v. a. ab September in sandigen Kiefernbeständen. Wegen Trockenheit ist das Vorkommen stark niederschlagsabhängig. Naturpark-/Schutzauflagen strikt beachten (Auen und Reservate). Alle Funde vor dem Verzehr zwingend von der VAPKO-Pilzkontrolle prüfen lassen.', 'Einer der grössten Föhrenwälder Europas; Naturpark Pfyn-Finges; national bedeutende Rhone-Auen und Amphibienlaichgebiete; Illgraben mit grösstem Murgang-Gerinne der Alpen; einer der trockensten Standorte der Schweiz.', 'pfyn-finges.ch; hls-dhs-dss.ch Pfynwald; en.wikipedia.org Pfynwald; waldwissen.net Waldföhrensterben; pilzforum.eu Kiefernwald'),
('entremont_val_de_bagnes', 'Entremont / Val de Bagnes', ARRAY['VS']::text[], 'Alpental', 'Das Val de Bagnes ist ein südliches Rhone-Seitental im französischsprachigen Bezirk Entremont, das bei Sembrancher ins Val d''Entremont mündet und südlich von Martigny liegt. Verwaltungssitz ist Le Châble, bekanntester Ort der Höhenkurort Verbier (ca. 1500 m) auf einer Sonnenterrasse gegenüber dem Grand-Combin-Massiv. Im hinteren Haut Val de Bagnes liegen Dörfer wie Lourtier, Fionnay und Bonatchiesse.', 700, 2300, 'Naturnahes Alpental mit Fichten- und Lärchenwäldern, in Höhenlagen Arve, auf sauren kristallinen Böden; ausgedehnte Schutzgebiete im Haut Val de Bagnes. Lichte Lärchen-Fichten-Wälder an den besonnten Hängen, geschlossenere Fichtenbestände in tieferen, schattigeren Lagen.', ARRAY['Steinpilz','Eierschwamm','Maronenröhrling','Goldröhrling','Trompetenpfifferling','Semmelstoppelpilz']::text[], 'Pilzsaison August bis Oktober in den montan-subalpinen Wäldern oberhalb Le Châble/Verbier und im Haut Val de Bagnes (ca. 1000-2000 m). Goldröhrling unter Lärchen, Steinpilz und Maronenröhrling in Fichten-/Lärchenwald, Eierschwamm im feuchten Moos. Schutzgebiets-Auflagen beachten. Jeden Fund vor dem Verzehr von einer offiziellen VAPKO-Pilzkontrolle freigeben lassen.', 'Grand-Combin-Massiv (4314 m); Lac de Mauvoisin mit hoher Staumauer; ausgedehnte Naturschutzgebiete im Haut Val de Bagnes; Verbier als bekannter Ferienort; Mündung ins Val d''Entremont bei Sembrancher.', 'en.wikipedia.org Val de Bagnes; en.wikipedia.org Bagnes; verbier.ch Haut Val de Bagnes; valais.ch Verbier-Val de Bagnes; waldwissen.net SwissFungi'),
('valle_maggia', 'Valle Maggia (Maggiatal)', ARRAY['TI']::text[], 'Alpental', 'Das Maggiatal ist mit rund 570 km² das grösste Tal des Tessins und erstreckt sich etwa 50 km nordwärts von Locarno am Lago Maggiore. Es ist ein typisches Alpental mit zahlreichen wilden Seitentälern (Val Bavona, Val Lavizzara, Val Rovana). Hauptorte sind Maggia, Cevio, Avegno-Gordevio und Lavizzara mit charakteristischen Steinhaus-Dörfern.', 254, 3272, 'Unterhalb 1000 m dominieren Edelkastanien- und Eichenwälder sowie alte Kastanienselven und Walnussterrassen aus römischer Zeit. Über 1000 m gehen Laubwälder in Nadelwald (Fichte, Lärche) und alpine Zonen über. Untergrund silikatisch (Gneis, saure Böden), typisch für die Tessiner Südalpen.', ARRAY['Steinpilz','Eierschwamm/Pfifferling','Maronenröhrling','Edelreizker','Parasol','Totentrompete','Trompetenpfifferling']::text[], 'In den Kastanien- und Eichenwäldern der unteren Lagen (bis ~1000 m) erscheinen Steinpilze, Eierschwämme, Maronen und Edelreizker typischerweise von Spätsommer bis Herbst (Aug–Okt) nach Regen; auf den sauren Gneis-Böden gedeihen Röhrlinge und Pfifferlinge gut. In höheren Nadelwaldlagen verschiebt sich die Saison nach hinten. Funde IMMER vor dem Verzehr von der offiziellen VAPKO-Pilzkontrolle prüfen lassen.', 'Höchster Gipfel Basòdino (3272 m); Talboden bei Ponte Brolla 254 m; wilde Seitentäler wie das Val Bavona; ausgedehnte Kastanienselven; grösstes Tal des Kantons (ein Fünftel des Tessins).', 'Wikipedia Maggiatal/Valle Maggia (de/en), Switzerland Tourism MySwitzerland, Ascona-Locarno Tourismus'),
('valle_verzasca', 'Valle Verzasca (Verzascatal)', ARRAY['TI']::text[], 'Alpental', 'Das Verzascatal ist ein wildes, steiles Tal im Bezirk Locarno zwischen Leventina und Maggiatal, rund 25 km in Nord-Süd-Richtung. Es ist berühmt für den smaragdgrünen Fluss Verzasca und die Steinbogenbrücke Ponte dei Salti bei Lavertezzo. Hauptdörfer sind Mergoscia, Vogorno, Corippo, Lavertezzo, Brione, Frasco und Sonogno.', 490, 2400, 'Talboden auf 500–900 m; im südlichen Talbereich dominiert die Edelkastanie unterhalb 1000 m, darüber Berg- und Nadelwald bis zur alpinen Zone über 2000 m. Untergrund silikatisch (Verzasca-Gneis/Serizzo, saure Böden). Steile, stark bewaldete Hänge mit vielen Felsplatten.', ARRAY['Steinpilz','Eierschwamm/Pfifferling','Maronenröhrling','Totentrompete','Trompetenpfifferling','Parasol']::text[], 'In den Kastanienwäldern der Sonnenhänge unter 1000 m wachsen Steinpilze, Eierschwämme und Maronen typischerweise von August bis Oktober nach Niederschlägen; die sauren Gneis-Böden begünstigen Röhrlinge und Pfifferlinge. In den steileren Bergwäldern Vorsicht beim Gelände. Funde IMMER vor dem Verzehr bei der VAPKO-Pilzkontrolle abklären lassen.', 'Berge bis ~2400 m; smaragdgrüner Fluss Verzasca; Ponte dei Salti bei Lavertezzo; Sonogno als letztes Dorf; gefärbter Serizzo-Gneis.', 'Wikipedia Verzascatal (de), Ascona-Locarno Tourismus, ticino.ch, lakeview.eu'),
('valle_di_blenio', 'Valle di Blenio (Bleniotal)', ARRAY['TI']::text[], 'Alpental', 'Das Bleniotal (Valle del Sole) wird vom Brenno durchflossen und reicht vom Lukmanierpass bis zur Mündung in den Tessin bei Biasca. Dank Nord-Süd-Ausrichtung und Breite ist es sehr sonnig. Hauptorte sind Acquarossa, Olivone und Malvaglia; Olivone liegt am Fuss des pyramidenförmigen Sosto.', 389, 3402, 'Vom Lukmanierpass (1914 m) bis zu den sanften Hügeln von Malvaglia (389 m). Untere Lagen mit Edelkastanienwäldern, darüber Berg-Nadelwald (Fichte, Lärche, Arve) bis zur alpinen Zone. Untergrund überwiegend silikatisch (Lepontinische Alpen, saure Böden), im oberen Talbereich teils kalkhaltige Einlagerungen.', ARRAY['Steinpilz','Eierschwamm/Pfifferling','Maronenröhrling','Edelreizker','Krause Glucke','Semmelstoppelpilz','Parasol']::text[], 'In den Kastanienwäldern der unteren Lagen erscheinen Steinpilze, Eierschwämme und Maronen ab Spätsommer (Aug–Okt); in den Fichten- und Föhrenwäldern der mittleren Höhen gedeihen Edelreizker, Krause Glucke und Semmelstoppelpilze. Nach Regenperioden besonders ergiebig. Jeden Fund IMMER vor dem Verzehr von der offiziellen VAPKO-Pilzkontrolle bestimmen lassen.', 'Lukmanierpass als Talschluss; Valle del Sole (Sonnental); Olivone am Fuss des Sosto; romanische Kirchen und Kastanienwälder.', 'Wikipedia Valle di Blenio (de), bellinzonaevalli.ch, Switzerland Tourism, ti-valle-di-blenio.ch'),
('leventina', 'Leventina (Livinental)', ARRAY['TI']::text[], 'Alpental', 'Die Valle Leventina erstreckt sich in einem rund 50 km langen Bogen vom Gotthardmassiv (Airolo) hinunter nach Biasca und wird vom Tessin durchflossen. Sie gliedert sich in Alta, Media und Bassa Leventina. Hauptorte sind Airolo, Quinto, Faido (Bezirkshauptort, 721 m) und die unteren Weindörfer.', 293, 3402, 'Talboden der Alta Leventina zwischen 950 m (Rodi-Fiesso) und 1150 m (Airolo), unten bei Biasca unter 300 m mit Reben. Ausgedehnte Föhren- und Nadelwälder (Wald-/Bergföhre, Fichte, Lärche) in den höheren Lagen, Edelkastanien und Mischwald in den unteren. Untergrund kristallin-silikatisch (Gotthardmassiv, saure Böden).', ARRAY['Steinpilz','Eierschwamm/Pfifferling','Maronenröhrling','Edelreizker','Semmelstoppelpilz','Parasol']::text[], 'Die ausgedehnten Föhren- und Nadelwälder begünstigen Edelreizker, Semmelstoppelpilze und Steinpilze, typischerweise von Spätsommer bis Herbst (Aug–Okt) nach Regen; in den Kastanien-/Mischwäldern der unteren Lagen auch Eierschwämme und Maronen. Auf den sauren Böden gedeihen Röhrlinge gut. Funde IMMER vor dem Verzehr bei der VAPKO-Pilzkontrolle prüfen lassen.', 'Gotthardmassiv-Gipfel über 3000 m; 50-km-Talbogen Airolo–Biasca; Strada Bassa Leventina; Dazio Grande; grosse Föhrenwälder.', 'Wikipedia Valle Leventina (de), HLS, Airolo/Faido Tourismus, ausflugsziele.ch'),
('malcantone', 'Malcantone', ARRAY['TI']::text[], 'Hügelland', 'Der Malcantone ist eine eigenständige Hügellandschaft südwestlich von Lugano, zwischen dem Luganersee bei Agno und dem Monte Lema. Sanfte, bewaldete Hänge mit malerischen Tessiner Dörfern wie Arosio, Mugena, Vezio, Fescoggia und Breno prägen die Region, die als Land der Kastanien gilt.', 270, 1624, 'Höhenzüge zwischen ~270 m (Luganersee) und 1624 m (Monte Lema). Ausgedehnte Edelkastanienwälder (Selven) und Mischwald, in höheren Lagen Buchen. Untergrund überwiegend silikatisch (Südalpen-Kristallin, saure bis leicht saure Böden), ideal für Kastanien.', ARRAY['Steinpilz','Eierschwamm/Pfifferling','Maronenröhrling','Parasol','Totentrompete','Trompetenpfifferling']::text[], 'Die ausgedehnten Kastanienselven und Mischwälder bringen im Herbst (Sep–Okt, Kastanienzeit) Steinpilze, Eierschwämme, Maronen und Totentrompeten hervor, besonders nach Regenperioden auf den sauren Böden. Der Malcantone ist eine klassische Sammelregion. Funde IMMER vor dem Verzehr von der offiziellen VAPKO-Pilzkontrolle bestimmen lassen.', 'Monte Lema (1624 m); Sentiero del Castagno (Kastanienweg) ab Arosio; alte Kastanienselven, Trockenhäuser (grà) und Köhlerplätze.', 'Switzerland Tourism (Malcantone – Land of Chestnuts), wegwandern.ch, ticinoweekend.ch, ticinotopten.ch'),
('mendrisiotto', 'Mendrisiotto', ARRAY['TI']::text[], 'Hügelland', 'Das Mendrisiotto ist der südlichste Teil der Schweiz, ein hügeliges Weinbaugebiet zwischen Luganersee und der italienischen Grenze, überragt vom Monte Generoso (1704 m) und dem Monte San Giorgio. Dörfer wie Arzo, Rancate, Tremona, Besazio, Ligornetto und Meride sowie das versteckte Valle di Muggio gehören dazu.', 270, 1704, 'Von ~270 m (Capolago am Luganersee) bis 1704 m (Monte Generoso). Dichte Laubwälder mit Buchenwald, Kastanien und Eichen; am Monte Generoso seltene Waldgesellschaften (Stechpalmen-Buchenwald, Hopfenbuchen-Eschenwald). Untergrund am Monte Generoso überwiegend kalkig (jurassischer Kalkstein), daneben versauerte Moränen mit Kastanieneichenwäldern.', ARRAY['Steinpilz','Eierschwamm/Pfifferling','Sommersteinpilz','Maronenröhrling','Parasol','Semmelstoppelpilz','Totentrompete']::text[], 'In den kalkreichen Buchenwäldern am Monte Generoso erscheinen Steinpilze und Sommersteinpilze sowie Eierschwämme typischerweise von Frühsommer bis Herbst (Juni–Okt) nach Regen; auf den versauerten Moränen mit Kastanieneichen zusätzlich Maronen. Kalkböden begünstigen andere Arten als die Gneis-Täler des Nordtessins. Jeden Fund IMMER vor dem Verzehr bei der VAPKO-Pilzkontrolle prüfen lassen.', 'Monte Generoso (1704 m, Zahnradbahn ab Capolago); Monte San Giorgio (UNESCO-Fossilien); Valle di Muggio; südlichster Punkt der Schweiz; kalkreiche Buchenwälder.', 'Wikipedia/Switzerland Tourism, mendrisiottoturismo.ch, montegeneroso.ch (Geologie), schweizer-wanderwege.ch (Naturparks), ticino.ch (Waldreservat Monte Generoso)'),
('zuercher_oberland', 'Zürcher Oberland', ARRAY['ZH']::text[], 'Voralpen', 'Das Zürcher Oberland ist der hügelige Südosten des Kantons Zürich (Bezirke Uster, Hinwil, Pfäffikon und das Tösstal bis Winterthur), angrenzend an das Toggenburg. Es ist geprägt von steilen, bewaldeten Hügeln, stattlichen Dörfern, Weilern und Streusiedlungen mit zahlreichen Bauernhöfen.', 440, 1292, 'Das Tössbergland (Hörnli-Gebiet) liegt zwischen 700 und 1300 m. Mischwald über 800–900 m, darunter Buchenwald; steile, stark bewaldete Tobel und gerodete Eggen mit Wiesen. Untergrund Molasse und Nagelfluh (Konglomerat), teils kalkhaltig. Höchster Punkt Schnebelhorn (1292 m).', ARRAY['Steinpilz','Eierschwamm/Pfifferling','Maronenröhrling','Parasol','Semmelstoppelpilz','Krause Glucke','Trompetenpfifferling']::text[], 'In den Buchen- und Mischwäldern der bewaldeten Hügel und Tobel wachsen Steinpilze, Eierschwämme und Maronen typischerweise von Spätsommer bis Herbst (Aug–Okt) nach Regen; in Fichten-/Mischbeständen auch Semmelstoppelpilze und Krause Glucke. Die Nagelfluh-/Molasse-Böden tragen eine vielfältige Mykoflora. Funde IMMER vor dem Verzehr von der VAPKO-Pilzkontrolle prüfen lassen.', 'Schnebelhorn (1292 m, höchster Punkt des Kantons Zürich); Bachtel, Hörnli, Tössstock; bewaldete Nagelfluh-Hügel und Tobel.', 'Wikipedia Zürcher Oberland/Tössbergland (de/en), SAC, schweizer-regionen.ch'),
('toesstal', 'Tösstal', ARRAY['ZH','SG']::text[], 'Tal', 'Das Tösstal ist eine Region im Osten des Kantons Zürich entlang der Töss, deren Quellbäche im Kanton St. Gallen am Tössstock entspringen. Hauptgemeinden im oberen Teil sind Fischenthal, Bauma, Wila, Turbenthal und Zell. Das Tal wurde von Linth-Gletscher und Töss geprägt.', 400, 1315, 'Tössscheidi auf 796 m, Talboden zwischen ~400 und 800 m, umgebende Höhen bis 1315 m (Höchhand). Steile Nagelfluhwände, tief eingeschnittene Tobel mit Wasserfällen und wilde Wälder (Buchen- und Mischwald, in höheren Lagen Fichten). Untergrund Molasse/Nagelfluh, teils kalkhaltig.', ARRAY['Steinpilz','Eierschwamm/Pfifferling','Maronenröhrling','Parasol','Semmelstoppelpilz','Krause Glucke']::text[], 'Die wilden Buchen- und Mischwälder an den steilen Talflanken und Tobeln bringen von Spätsommer bis Herbst (Aug–Okt) Steinpilze, Eierschwämme und Maronen hervor, besonders nach Regen; in Fichtenbeständen auch Semmelstoppelpilze und Krause Glucke. In Naturschutzgebieten gelten Sammelbeschränkungen. Jeden Fund IMMER vor dem Verzehr bei der VAPKO-Pilzkontrolle prüfen lassen.', 'Quellgebiet der Töss am Tössstock; Tössscheidi (796 m); Höchhand (1314 m), Schwarzenberg (1293 m); Nagelfluhwände, Tobel und Wasserfälle als Naturschutzgebiet.', 'Wikipedia Tösstal/Töss/Fischenthal (de/en), schweizerfluss.ch, wanderungen.ch'),
('zuercher_weinland', 'Zürcher Weinland', ARRAY['ZH']::text[], 'Hügelland', 'Das Zürcher Weinland liegt im Norden des Kantons Zürich zwischen Thur und Rhein und vereint sanfte Hügel, sonnige Rebhänge und historische Dörfer. Wirtschaftliches Zentrum sind Andelfingen und Kleinandelfingen, dazu Ossingen, die Stammheimer Dörfer und Marthalen. Im Norden bildet der Rhein die Grenze.', 350, 600, 'Sanftes Hügelland zwischen ~350 und 600 m (z.B. Uhwiesen 450 m am Cholfirst). Über ein Drittel der Fläche bewaldet: Buchen- und Eichen-Mischwald auf Molasse, teils kalkhaltige Böden, ergänzt durch Föhren und Fichten. Daneben Reben und Ackerbau.', ARRAY['Steinpilz','Eierschwamm/Pfifferling','Maronenröhrling','Parasol','Sommersteinpilz','Semmelstoppelpilz']::text[], 'In den ausgedehnten Buchen- und Eichenwäldern (z.B. Cholfirst) erscheinen Steinpilze, Sommersteinpilze, Eierschwämme und Maronen typischerweise von Frühsommer bis Herbst (Juni–Okt) nach Regen; auf kalkhaltigen Böden eine andere Artenzusammensetzung als im sauren Bergland. Funde IMMER vor dem Verzehr von der VAPKO-Pilzkontrolle prüfen lassen.', 'Grösstes Weinbaugebiet des Kantons (~220 ha); Cholfirst-Wald; Rheinfall bei Schloss Laufen (grösster Wasserfall Europas); Schiterberg als steilster Rebberg des Kantons.', 'Wikipedia/zuercher-weinland.ch, Gemeinde Feuerthalen, schweizer-regionen.ch, MySwitzerland'),
('freiamt', 'Freiamt', ARRAY['AG']::text[], 'Hügelland', 'Das Freiamt ist eine sanfte Hügellandschaft im Südosten des Kantons Aargau zwischen Reuss und Lindenberg, umfassend die Bezirke Bremgarten und Muri (40 Gemeinden). Es ist geprägt von ruhigen Wäldern, sanften Höhenzügen, kleinen Dörfern, historischen Kirchen und Klöstern wie Muri. Wohlen ist das wirtschaftliche Zentrum.', 380, 878, 'Hügelland zwischen ~380 m (Reuss) und 878 m (Lindenberg, Rüedikerwald). Mischlaubwald mit Buche und Tanne als Hauptbaumarten, dazu wirtschaftlich angepflanzte Fichten; an den Hängen Moränen des Reussgletschers. Untergrund Molasse-Sandstein, teils kalkhaltig.', ARRAY['Steinpilz','Eierschwamm/Pfifferling','Maronenröhrling','Parasol','Semmelstoppelpilz','Krause Glucke','Sommersteinpilz']::text[], 'In den Buchen-Tannen-Mischwäldern und Fichtenbeständen am Lindenberg und entlang der Reuss wachsen Steinpilze, Eierschwämme, Maronen und Semmelstoppelpilze typischerweise von Spätsommer bis Herbst (Aug–Okt) nach Regen; in der Reuss-Auenlandschaft eine eigene Artenpalette. Funde IMMER vor dem Verzehr bei der VAPKO-Pilzkontrolle bestimmen lassen.', 'Lindenberg (878 m) mit Molasse-Sandstein; Reusstal und Auenlandschaft; Kloster Muri; sanftes Hügelland zwischen Reuss und Lindenberg; Freiämterweg.', 'Wikipedia Freiamt/Lindenberg (de), Aargau Tourismus, freiamt.ch, Kanton Aargau Waldstandorte-PDF (ag.ch)')
